const $=s=>document.querySelector(s),money=n=>'$'+Math.round(n).toLocaleString('es-MX'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let people=[];
let projectRecords=[];
function selectedPeriod(){return year+'-'+String(month).padStart(2,'0')}
function personEarnings(k){const p=people[k],brands=clients.filter(c=>c.active&&c.fee>0&&c.team.includes(k)&&personInPayroll(p,selectedPeriod())),retainers=brands.reduce((sum,c)=>sum+c.comm[c.team.indexOf(k)],0),projects=projectRecords.filter(pr=>pr.period===selectedPeriod()).flatMap(pr=>pr.assignments.filter(a=>a.person===k).map(a=>({name:pr.name,client:projectClientName(pr),...a,amount:a.amount,paid:commissionParts(a).status==='Pagada'}))),projectPay=projects.reduce((sum,pr)=>sum+pr.amount,0);return {brands,retainers,projects,projectPay,base:personBaseForPeriod(p,selectedPeriod()),total:personBaseForPeriod(p,selectedPeriod())+retainers+projectPay}}
let clients=[];
let contents={},page='Vista General',tab='Activos',filter='Todos',selected=0,month='11',year='2026';const names=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];const navs=[['Vista General','◫'],['Clientes','◉'],['Igualas','↻'],['Proyectos','◇'],['Colaboradores','◎'],['Contenido','▦'],['Calendario','▥'],['Gastos','≡'],['Flujo','⇄'],['Finanzas','↗']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3000)}
function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">CLANDESTINO STUDIO / WORKSPACE</div><h1>${title}</h1><div class="sub">${sub}</div></div><div class="controls">${action}</div></div>`}
function monthselect(){return `<select aria-label="Mes" onchange="month=this.value;render()">${names.map((n,i)=>`<option value="${i+1}" ${+month===i+1?'selected':''}>${n}</option>`).join('')}</select><select aria-label="Año" onchange="year=this.value;render()"><option ${year==='2026'?'selected':''}>2026</option><option ${year==='2025'?'selected':''}>2025</option></select>`}
function go(p){page=p;tab='Activos';filter='Todos';render()}
function render(){document.body.classList.toggle('clientreviewmode',page==='Vista cliente'); $('#nav').innerHTML=navs.map(([p,i])=>`<button class="${page===p?'active':''}" onclick="go('${p}')"><span>${i}</span>${p}</button>`).join('');$('#crumb').textContent='Workspace / '+page;$('#app').innerHTML=page==='Vista General'?home():page==='Igualas'?retainersView():page==='Clientes'?clientview():page==='Colaboradores'?payroll():page==='Contenido'?contentlist():page==='Marca'?brand():page==='Vista cliente'?clientReviewView():page==='Proyectos'?projects():page==='Calendario'?calendarView():page==='Gastos'?expensesView():page==='Flujo'?flowView():finance();applyStateTones();updateNotificationBadge();}
const salehistory=[360000,389000,420000,405000,450000,472000,460000,488000,510000,540000];const profithistory=[120000,139000,160000,145000,175000,187000,170000,198000,210000,230000];
function totals(period=selectedPeriod()){const ac=clients.filter(c=>c.active),m=monthlySummary(monthlyRows(period)),fees=m.fee,collected=m.paid,prs=projectRecords.filter(pr=>pr.period===period),projectSales=prs.reduce((n,pr)=>n+pr.amount,0),pay=ac.reduce((a,c)=>a+c.comm.reduce((x,y,j)=>x+(personInPayroll(people[c.team[j]],period)?y:0),0),0)+people.reduce((a,p)=>a+personBaseForPeriod(p,period),0)+prs.reduce((sum,pr)=>sum+pr.assignments.reduce((n,a)=>n+a.amount,0),0),expenses=expenseTotals(period);return {fees,collected,pay,projectSales,...expenses,sales:fees+projectSales,cost:pay+expenses.fixed+expenses.variable+expenses.investment,paid:collected+prs.reduce((n,pr)=>n+pr.paid,0)}}
function annualAmounts(){const ss=Array(12),pp=Array(12);if(+year===2026){salehistory.forEach((v,i)=>ss[i]=v);profithistory.forEach((v,i)=>pp[i]=v)}for(let i=0;i<12;i++){const period=year+'-'+String(i+1).padStart(2,'0');if(monthlyRows(period).length||expenseRecords.some(r=>r.date.slice(0,7)===period)||projectRecords.some(pr=>pr.period===period)){const t=totals(period);ss[i]=t.sales;pp[i]=t.sales-t.cost}}return {ss,pp}}
function expenseMoney(value){return (value>0?'-':'')+paymentMoney(value)}
function homeActivity(){const brands=clients.filter(c=>c.active&&c.fee>0).length,projects=projectRecords.filter(pr=>pr.period===selectedPeriod()&&pr.status!=='Terminado').length;return `<section class="homeactivity" aria-label="Actividad del estudio"><div class="card activityrow"><div><h3>Marcas activas</h3><small>Clientes activos con iguala mensual</small></div><strong>${brands}</strong></div><div class="card activityrow"><div><h3>Proyectos en curso</h3><small>${names[+month-1]} ${year} · Sin terminar</small></div><strong>${projects}</strong></div></section>`}
function home(){const t=totals(),{ss,pp}=annualAmounts();return heading('Vista General','Ventas, gastos y utilidad del mes en un solo lugar.',monthselect())+`<section class="overviewstatement" aria-label="Resumen mensual"><div class="statementblock"><div class="statementrow"><span>Venta por igualas</span><strong>${paymentMoney(t.fees)}</strong></div><div class="statementrow"><span>Venta por proyectos</span><strong>${paymentMoney(t.projectSales)}</strong></div><h2>Venta total</h2><div class="statementtotal">${paymentMoney(t.sales)}</div></div><div class="statementblock expensesstatement">${[['Gastos fijos',t.fixed,'Gastos'],['Gastos variables',t.variable,'Gastos'],['Gastos inversión',t.investment,'Gastos'],['Nómina',t.pay,'Colaboradores']].map(([label,value,section])=>`<button class="statementrow" onclick="go('${section}')"><span>${label}</span><strong>${section==='Gastos'?expenseMoney(value):paymentMoney(value)} <span aria-hidden="true">↗</span></strong></button>`).join('')}<h2>Utilidad</h2><div class="statementtotal profitamount">${paymentMoney(t.sales-t.cost)}</div><p class="hint">Venta total − gastos fijos − gastos variables − inversión − nómina. Calculada sobre la venta total del mes.</p></div></section>${homeActivity()}<div class="sectionline"><h2>Crecimiento anual</h2><div class="legend"><span><i class="dot"></i>Venta total</span><span><i class="dot light"></i>Utilidad después de inversión</span></div></div><div class="chartbox"><div class="cardline"><span class="hint">${year} / Evolución mensual · Datos ilustrativos</span><span class="pill">${names[+month-1]} ${year}</span></div><div class="chart">${names.map((n,i)=>`<div class="month ${ss[i]===undefined?'future':''}"><div class="bar" style="height:${(ss[i]||0)/550000*100}%" title="${n}: venta ${money(ss[i]||0)}"></div><div class="bar profitbar" style="height:${Math.max(0,pp[i]||0)/550000*100}%" title="${n}: utilidad ${money(pp[i]||0)}"></div></div>`).join('')}</div><div class="chartlabels">${names.map(n=>`<span>${n.slice(0,3)}</span>`).join('')}</div><div class="annual"><table><thead><tr><th>${year}</th>${names.map(n=>`<th>${n.slice(0,3)}</th>`).join('')}</tr></thead><tbody>${[['Venta total',ss],['Utilidad',pp],['Margen',ss.map((v,i)=>pp[i]/v*100)]].map(([l,arr])=>`<tr><td>${l}</td>${names.map((n,i)=>`<td>${arr[i]===undefined?'—':l==='Margen'?arr[i].toFixed(1)+'%':money(arr[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><p class="hint">Datos de ejemplo del prototipo. La gráfica usa los registros de cada mes; enero a octubre de 2026 conservan cifras ilustrativas donde no hay registros. Utilidad incluye inversión, según tu fórmula.</p>`}
function clientview(){const list=clients.map((c,i)=>({c,i})).filter(({c})=>c.active===(tab==='Activos'));return heading('Clientes','Directorio de marcas, contactos y equipos del estudio.',`<button class="primary" onclick="newclient()">+ Dar de alta</button>`)+`<div class="toolbar"><div class="tabs">${['Activos','Inactivos'].map(t=>`<button class="${tab===t?'selected':''}" onclick="tab='${t}';render()">${t} <small style="display:inline">${clients.filter(c=>c.active===(t==='Activos')).length}</small></button>`).join('')}</div><input class="search" aria-label="Buscar cliente o contacto" placeholder="Buscar marca o contacto…" oninput="filterrows(this.value)"></div><div class="tablewrap"><table class="crmtable"><thead><tr><th>MARCA</th><th>CONTACTO DIRECTO</th><th>DIRECCIÓN DEL NEGOCIO</th><th>IGUALA MENSUAL</th><th>EQUIPO</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map(({c,i})=>`<tr data-name="${esc([c.name,c.contactName,c.email,c.phone,c.address].filter(Boolean).join(' ').toLowerCase())}"><td class="brandname">${esc(c.name)}</td><td><strong>${esc(c.contactName||'Sin contacto registrado')}</strong><small>${esc(c.email||'Sin correo')}</small><small>${esc(c.phone||'Sin teléfono')}</small></td><td class="crmaddress">${esc(c.address||'Sin dirección registrada')}</td><td>${money(c.fee)}</td><td><div class="teammates">${c.team.map(k=>`<span class="avatar" title="${esc(people[k].name+' / '+people[k].role)}">${initials(people[k].name)}</span>`).join('')}</div></td><td><span class="pill">${c.active?'Activo':'Inactivo'}</span></td><td><div class="clientactions"><button onclick="editclient(${i})">Editar</button><button onclick="clientHistory(${i})">Historial</button><button onclick="toggleclient(${i})" style="border:0">${c.active?'Dar de baja':'Reactivar'}</button></div></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No hay clientes en esta pestaña.</div>'}</div><p class="hint">Todos los datos del cliente se pueden editar. Los cobros se administran en Igualas. Los cambios se guardan en Supabase; revisa el indicador de guardado antes de salir.</p>`}
// Monthly snapshots keep each period's charges and payments independent.
let retainerMonths={},retainerFilter='Todos',retainerSearch='';
function monthlyRows(period=selectedPeriod()){return retainerMonths[period]||[]}
function visibleRetainers(){return monthlyRows().filter(r=>(retainerFilter==='Todos'||(retainerFilter==='Pagados'?r.paid>=r.fee:r.paid<r.fee))&&r.name.toLowerCase().includes(retainerSearch.toLowerCase()))}
function monthlySummary(rows){return rows.reduce((a,r)=>({fee:a.fee+r.fee,paid:a.paid+r.paid,pending:a.pending+Math.max(0,r.fee-r.paid)}),{fee:0,paid:0,pending:0})}
function retainerMonthSelect(){return `<select aria-label="Mes de igualas" onchange="month=this.value;render()">${names.map((n,i)=>`<option value="${i+1}" ${+month===i+1?'selected':''}>${n}</option>`).join('')}</select><select aria-label="Año de igualas" onchange="year=this.value;render()">${Array.from({length:8},(_,i)=>2027-i).map(y=>`<option ${+year===y?'selected':''}>${y}</option>`).join('')}</select>`}
function generateRetainers(){const period=selectedPeriod();if(retainerMonths[period])return;retainerMonths[period]=clients.map((c,i)=>({c,i})).filter(({c})=>c.active&&c.fee>0&&(!c.start||c.start<=period)).map(({c,i})=>({client:i,name:c.name,fee:c.fee,day:c.day,paid:0,payments:[]}));render();toast('Igualas generadas para '+names[+month-1]+' '+year)}
function retainersView(){const rows=visibleRetainers(),sum=monthlySummary(rows),all=monthlySummary(monthlyRows());return heading(`Igualas <span class="retainer-month">· ${names[+month-1]} ${year}</span>`,'Cobros e historial separados por mes.',retainerMonthSelect())+`<div class="receivable monthlybalance"><div><div class="label">Total de igualas</div><div class="value">${paymentMoney(all.fee)}</div></div><div><div class="label">Cobrado del mes</div><div class="value">${paymentMoney(all.paid)}</div></div><div><div class="label">Por cobrar</div><div class="value">${paymentMoney(all.pending)}</div></div></div><div class="toolbar"><div class="tabs" aria-label="Filtrar igualas">${['Todos','Por cobrar','Pagados'].map(f=>`<button class="${retainerFilter===f?'selected':''}" onclick="retainerFilter='${f}';render()">${f} <small style="display:inline">${monthlyRows().filter(r=>f==='Todos'||(f==='Pagados'?r.paid>=r.fee:r.paid<r.fee)).length}</small></button>`).join('')}</div><input class="search" aria-label="Buscar iguala" placeholder="Buscar marca…" value="${esc(retainerSearch)}" onchange="retainerSearch=this.value;render()"></div><div class="filtertotals" role="status"><strong>${retainerFilter} · ${rows.length} marcas</strong><span>Total: ${paymentMoney(sum.fee)}</span><span>Cobrado: ${paymentMoney(sum.paid)}</span><span>Por cobrar: <strong>${paymentMoney(sum.pending)}</strong></span></div><div class="tablewrap"><table><thead><tr><th>MARCA</th><th>IGUALA DEL MES</th><th>FECHA DE PAGO</th><th>COBRADO</th><th>POR COBRAR</th><th>ESTADO</th><th>COBRO</th><th>PAGOS REGISTRADOS</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="brandname">${esc(r.name)}</td><td>${paymentMoney(r.fee)}</td><td>${Math.min(r.day,new Date(+year,+month,0).getDate())} de ${names[+month-1]}</td><td>${paymentMoney(r.paid)}</td><td>${paymentMoney(Math.max(0,r.fee-r.paid))}</td><td><span class="pill">${r.paid>=r.fee?'Pagado':r.paid?'Pago parcial':'Por cobrar'}</span></td><td>${r.paid<r.fee?`<button class="paymentaction retainerpayaction" onclick="payment(${r.client},'${selectedPeriod()}')">Registrar pago</button>`:'<span class="pill retainerpayaction">Liquidado</span>'}</td><td><button class="editretainerpayments" onclick="retainerPayments(${r.client},'${selectedPeriod()}')">Ver / editar pagos</button></td></tr>`).join('')}</tbody><tfoot><tr><td>TOTAL · ${retainerFilter.toUpperCase()}</td><td>${paymentMoney(sum.fee)}</td><td></td><td>${paymentMoney(sum.paid)}</td><td>${paymentMoney(sum.pending)}</td><td colspan="3"></td></tr></tfoot></table>${!rows.length?`<div class="empty">${retainerMonths[selectedPeriod()]?'No hay igualas para este filtro.':'No hay registros de igualas para este mes. No se han importado datos históricos.'}</div>`:''}</div>${!retainerMonths[selectedPeriod()]?`<button class="wide" onclick="generateRetainers()">Generar igualas de ${names[+month-1]} ${year}</button><p class="hint">Genera cargos sin pagos a partir de las marcas activas y sus importes actuales. Para meses pasados, verifica estos datos antes de registrar cobros.</p>`:''}<p class="hint">Prototipo: el historial por mes se conserva durante esta sesión. Al recargar vuelve a los datos de ejemplo de noviembre; el guardado permanente se conectará con la base de datos.</p>`}
function initials(n){return n.split(' ').slice(0,2).map(w=>w[0]).join('')}
function filterrows(v){document.querySelectorAll('tr[data-name]').forEach(r=>r.style.display=r.dataset.name.includes(v.toLowerCase())?'':'none')}
function openmodal(s){$('#modal').innerHTML=s;applyStateTones($('#modal'));$('#modal').showModal()}
function closemodal(){if(editingPiece){editingPiece.controller?.abort();editingPiece=null}$('#modal').close()}
function modalhead(t){return `<div class="modalhead"><h2>${t}</h2><button onclick="closemodal()" aria-label="Cerrar">✕</button></div>`}
const clientRoles=['Marketing','Fotografía / Video','Diseño'];const collaboratorRoles=[...clientRoles,'Administración'];
function newclient(){clientform()}
function editclient(i){if(clients[i])clientform(i)}
function clientform(i=null){
 const editing=i!==null,c=editing?clients[i]:{name:'',fee:'',day:1,start:'2026-11',active:true,team:clientRoles.map(role=>people.findIndex(p=>!p.deletedAt&&p.role===role)),comm:[0,0,0]};
 openmodal(modalhead(editing?'Editar cliente':'Dar de alta cliente')+`<form onsubmit="saveclient(event,${editing?i:'null'})"><div class="formgrid"><label>Cliente / marca<input name="name" value="${esc(c.name)}" maxlength="120" required></label><label>Nombre del contacto directo<input name="contactName" value="${esc(c.contactName||'')}" maxlength="120" autocomplete="name"></label><label>Correo del contacto<input name="email" type="email" value="${esc(c.email||'')}" maxlength="254" autocomplete="email"></label><label>Teléfono del contacto<input name="phone" type="tel" value="${esc(c.phone||'')}" maxlength="40" autocomplete="tel"></label><label class="crmfull">Dirección de la marca o negocio<textarea name="address" maxlength="500" autocomplete="street-address" placeholder="Calle, número, colonia, ciudad y código postal">${esc(c.address||'')}</textarea></label><label>Iguala mensual ($)<input name="fee" type="number" min="0" step="0.01" value="${c.fee}" required><small>Deja $0 si solo contrata proyectos; no generará igualas ni comisiones mensuales.</small></label><label>Día de pago<input name="day" type="number" min="1" max="31" value="${c.day}" required></label><label>Mes de inicio<input name="start" type="month" value="${esc(c.start||'2026-11')}" required></label><label>Estado del cliente<select name="active" style="width:100%;margin-top:7px"><option value="true" ${c.active?'selected':''}>Activo</option><option value="false" ${!c.active?'selected':''}>Inactivo</option></select></label></div><div class="sectionline"><h2>Equipo y comisiones mensuales</h2></div>${clientRoles.map((r,j)=>`<div class="formgrid" style="margin-bottom:12px"><label>${r}<select style="width:100%;margin-top:7px" name="person${j}" required>${people.map((p,k)=>({p,k})).filter(({p,k})=>(!p.deletedAt&&p.role===r)||c.team[j]===k).map(({p,k})=>`<option value="${k}" ${c.team[j]===k?'selected':''}>${esc(p.name)}${p.deletedAt?' · Baja, reasignar':p.role!==r?' · Puesto actualizado':''}</option>`).join('')}</select></label><label>Comisión de ${r} ($)<input name="comm${j}" type="number" min="0" step="0.01" value="${c.comm[j]||0}" required></label></div>`).join('')}<div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary" type="submit">${editing?'Guardar cambios':'Guardar cliente'}</button></div><p class="hint">${editing?'Los cambios actualizan esta marca, su equipo, la nómina y el resumen. Se conservan los pagos y el contenido existentes. ':''}Demo temporal de noviembre 2026: el mes de inicio se guarda como dato; la vigencia histórica se incorporará en la app.</p></form>`)
}
function saveclient(e,i=null){
 e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),fee=Number(f.get('fee')),day=Number(f.get('day')),start=String(f.get('start')||''),team=[0,1,2].map(j=>Number(f.get('person'+j))),comm=[0,1,2].map(j=>Number(f.get('comm'+j)));
 if(!name||!Number.isFinite(fee)||fee<0||!Number.isInteger(day)||day<1||day>31||!/^\d{4}-\d{2}$/.test(start)||team.some((k,j)=>!Number.isInteger(k)||!people[k]||((people[k].deletedAt||people[k].role!==clientRoles[j])&&(i===null||clients[i]?.team[j]!==k)))||comm.some(n=>!Number.isFinite(n)||n<0)){toast('Revisa los datos del cliente y las comisiones');return}
 const contactName=String(f.get('contactName')||'').trim(),email=String(f.get('email')||'').trim(),phone=String(f.get('phone')||'').trim(),address=String(f.get('address')||'').trim();
 if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Revisa el correo del contacto');return}
 if(fee===0){team.length=0;comm.length=0}
 const previousTeam=i===null?[]:[...(clients[i]?.team||[])];const fields={name,contactName,email,phone,address,fee,day,start,team,comm,active:f.get('active')==='true'};
 if(i===null)clients.push({...fields,paid:0});else{if(!clients[i])return;Object.assign(clients[i],fields)}
 const clientIndex=i===null?clients.length-1:i;people.forEach((p,k)=>{if(!Array.isArray(p.brandAccess))return;if(team.includes(k)){if(!p.brandAccess.includes(clientIndex))p.brandAccess.push(clientIndex)}else if(previousTeam.includes(k))p.brandAccess=p.brandAccess.filter(id=>id!==clientIndex)});const monthly=retainerMonths[selectedPeriod()];if(monthly){const record=monthly.find(r=>r.client===clientIndex);if(record)Object.assign(record,{name,fee,day});else if(fields.active&&fee>0&&start<=selectedPeriod())monthly.push({client:clientIndex,name,fee,day,paid:0,payments:[]})}
 closemodal();render();toast(i===null?'Cliente creado · Equipo y nómina actualizados en la demo':'Cliente actualizado · Iguala, equipo y nómina recalculados')
}
function paymentFields(pending,p={},destination=false){return `<div class="formgrid"><label class="crmfull">Observaciones<textarea name="observations" maxlength="1500" placeholder="Referencia, anticipo, periodo o aclaración del pago">${esc(p.observations||'')}</textarea></label><label>Método de pago<select name="method" onchange="setPaymentDestination(this)" required style="width:100%;margin-top:7px">${['SPEI','Efectivo','Tarjeta','Depósito bancario','Otro'].map(m=>`<option ${p.method===m?'selected':''}>${m}</option>`).join('')}</select></label><label>Cuenta origen<input name="origin" maxlength="150" value="${esc(p.origin||'')}" placeholder="Banco / titular / últimos 4 dígitos o No aplica"></label>${destination?paymentDestinationField('destination',p.destination):''}<label>Fecha<input name="date" type="date" value="${esc(p.date??mexicoDay())}" required></label><label>Monto<input name="amount" type="number" min="0.01" step="0.01" max="${pending}" value="${p.amount??pending}" oninput="updateRetainerPaymentPreview(this.form)" required></label></div>`}
function payment(i,period=selectedPeriod()){const record=monthlyRows(period).find(r=>r.client===i);if(!record)return toast('Genera primero las igualas del mes');const pending=Math.max(0,record.fee-record.paid);if(!pending)return toast('Esta iguala ya está liquidada');openmodal(modalhead('Registrar pago · '+esc(record.name))+`<form data-retainer-balance="${pending}" onsubmit="savepayment(event,${i},'${period}')"><p>Iguala de ${names[Number(period.slice(5))-1]} ${period.slice(0,4)} · Saldo: <strong>${paymentMoney(pending)}</strong></p><p class="hint">Puedes registrar un abono menor al saldo. La diferencia quedará por cobrar.</p>${paymentFields(pending,{},true)}<p class="filtertotals" aria-live="polite" data-payment-preview></p><button class="primary wide">Guardar pago</button></form>`);updateRetainerPaymentPreview($('#modal form'))}
function readPayment(f){return {amount:Number(f.get('amount')),date:String(f.get('date')||''),method:String(f.get('method')||''),origin:String(f.get('origin')||'').trim(),observations:String(f.get('observations')||'').trim(),destination:String(f.get('destination')||'')}}
function validPayment(p,balance){return Number.isFinite(p.amount)&&p.amount>0&&p.amount<=Math.round(balance*100)/100&&/^\d{4}-\d{2}-\d{2}$/.test(p.date)&&['SPEI','Efectivo','Tarjeta','Depósito bancario','Otro'].includes(p.method)}
function applyRetainerPayment(i,period,amount,date,method,origin='',observations='',destination=''){const record=monthlyRows(period).find(r=>r.client===i),p={amount,date,method,origin,observations,destination,status:'Registrado'};if(!record||!validPayment(p,record.fee-record.paid)||!validPaymentDestination(p))return false;record.paid=Math.round((record.paid+amount)*100)/100;(record.payments??=[]).push(p);if(period==='2026-11'&&clients[i])clients[i].paid=record.paid;syncRetainerFlow(i,period);return true}
function savepayment(e,i,period=selectedPeriod()){e.preventDefault();const p=readPayment(new FormData(e.target));if(!applyRetainerPayment(i,period,p.amount,p.date,p.method,p.origin,p.observations,p.destination))return toast('Revisa los datos del pago');closemodal();render();toast('Pago registrado · Historial del cliente actualizado')}
function updateRetainerPaymentPreview(form){if(!form?.hasAttribute('data-retainer-balance'))return;const balance=Number(form.dataset.retainerBalance),amount=Number(form.elements.amount.value),cancelled=form.elements.paymentStatus?.value==='Anulado',date=form.elements.date;date.required=!cancelled;if(form.elements.destination)form.elements.destination.required=!cancelled;form.elements.amount.max=cancelled?Math.max(balance,amount):balance;const target=form.querySelector('[data-payment-preview]');if(target)target.textContent='Saldo por cobrar después de guardar: '+paymentMoney(Math.max(0,Math.round((balance-(cancelled?0:amount))*100)/100))}
function ensureRetainerLedger(record){record.payments??=[];const documented=record.payments.filter(p=>p.status!=='Anulado').reduce((n,p)=>n+p.amount,0),opening=Math.round((record.paid-documented)*100)/100;if(opening>0)record.payments.unshift({amount:opening,date:'',method:'Otro',origin:'',observations:'Importe inicial de ejemplo; fecha y cuenta no registradas',status:'Registrado'})}
function retainerPayments(i,period=selectedPeriod()){const record=monthlyRows(period).find(r=>r.client===i);if(!record)return;ensureRetainerLedger(record);openmodal(modalhead('Pagos de iguala · '+esc(record.name))+`<p>${esc(period)} · Iguala: ${paymentMoney(record.fee)} · Cobrado: ${paymentMoney(record.paid)} · Por cobrar: ${paymentMoney(Math.max(0,record.fee-record.paid))}</p><div class="tablewrap"><table><thead><tr><th>FECHA</th><th>MONTO</th><th>MÉTODO / CUENTA</th><th>ESTADO DEL REGISTRO</th><th></th></tr></thead><tbody>${record.payments.map((p,j)=>`<tr><td>${esc(p.date||'Sin registrar')}</td><td>${paymentMoney(p.amount)}</td><td>${esc(p.method)}<small>${esc(p.origin||'Sin cuenta registrada')}</small>${p.destination?`<small>Destino: ${esc(flowAccountName(p.destination))}</small>`:''}</td><td><span class="pill">${p.status==='Anulado'?'Anulado':'Registrado'}</span></td><td><button onclick="editRetainerPayment(${i},'${period}',${j})">Editar pago</button></td></tr>`).join('')||'<tr><td colspan="5">Aún no hay pagos registrados.</td></tr>'}</tbody></table></div><p class="hint">Puedes corregir los datos o anular un registro equivocado. Los anulados se conservan aquí y no cuentan como cobrado. El estado de la iguala se calcula con el dinero registrado.</p>${record.paid<record.fee?`<button class="paymentaction wide" onclick="payment(${i},'${period}')">Registrar abono</button>`:''}`)}
function editRetainerPayment(i,period,j){const record=monthlyRows(period).find(r=>r.client===i),p=record?.payments?.[j];if(!p)return;const balance=Math.round((record.fee-record.paid+(p.status==='Anulado'?0:p.amount))*100)/100;openmodal(modalhead('Editar pago · '+esc(record.name))+`<form data-retainer-balance="${balance}" onsubmit="saveRetainerPaymentEdit(event,${i},'${period}',${j})"><label>Estado del registro<select name="paymentStatus" onchange="updateRetainerPaymentPreview(this.form)" style="width:100%;margin-top:7px"><option ${p.status!=='Anulado'?'selected':''}>Registrado</option><option ${p.status==='Anulado'?'selected':''}>Anulado</option></select></label><p class="hint">Registrado cuenta como cobrado. Anulado devuelve ese importe al saldo por cobrar. Para pagos iniciales sin fecha, indica la fecha real al corregirlos.</p>${paymentFields(Math.max(balance,p.amount),p,true)}<p class="filtertotals" aria-live="polite" data-payment-preview></p><div class="formactions"><button type="button" onclick="retainerPayments(${i},'${period}')">Volver</button><button class="primary">Guardar corrección</button></div></form>`);updateRetainerPaymentPreview($('#modal form'))}
function reviseRetainerPayment(i,period,j,p,status){const record=monthlyRows(period).find(r=>r.client===i),old=record?.payments?.[j];if(!old||!['Registrado','Anulado'].includes(status))return false;const others=Math.round((record.paid-(old.status==='Anulado'?0:old.amount))*100)/100;if(status==='Registrado'?(!validPayment(p,record.fee-others)||!validPaymentDestination(p)):!(Number.isFinite(p.amount)&&p.amount>0&&['SPEI','Efectivo','Tarjeta','Depósito bancario','Otro'].includes(p.method)))return false;const revisions=[...(old.revisions||[]),{...old,revisions:undefined,changedAt:new Date().toISOString()}];record.payments[j]={...p,status,revisions};record.paid=Math.round((others+(status==='Anulado'?0:p.amount))*100)/100;if(period==='2026-11'&&clients[i])clients[i].paid=record.paid;syncRetainerFlow(i,period);return true}
function saveRetainerPaymentEdit(e,i,period,j){e.preventDefault();const f=new FormData(e.target);if(!reviseRetainerPayment(i,period,j,readPayment(f),f.get('paymentStatus')))return toast('Revisa los datos: el cobro no puede superar el saldo de la iguala');render();retainerPayments(i,period);toast('Pago corregido · Saldo e historial actualizados')}
function paymentDestinationField(name,value='',required=true){return `<label>Cuenta destino<select name="${name}" aria-label="Cuenta destino" onchange="setDestinationMethod(this)" ${required?'required':''} style="width:100%;margin-top:7px"><option value="">Seleccionar destino del pago</option>${flowAccounts.map(a=>`<option value="${a.id}" ${a.id===value?'selected':''}>${esc(a.name)}</option>`).join('')}</select><small>${name==='advanceDestination'?'Destino del anticipo. Si aún no hay anticipo, no se registra una entrada.':'El cobro genera automáticamente una entrada en esta cuenta de Flujo.'}</small></label>`}
function setDestinationMethod(select){const method=select.form?.elements[select.name==='advanceDestination'?'advanceMethod':'method'];if(!method)return;if(select.value==='cash')method.value='Efectivo';else if(select.value&&method.value==='Efectivo')method.value='SPEI'}
function setPaymentDestination(input,name='destination'){const target=input.form?.elements[name];if(target&&input.value==='Efectivo')target.value='cash'}
function validPaymentDestination(p){return flowAccounts.some(a=>a.id===p.destination)&&(p.method!=='Efectivo'||p.destination==='cash')}
function syncProjectFlow(i){const pr=projectRecords[i];if(!pr)return;flowRecords=flowRecords.filter(r=>r.sourceProject!==i);(pr.payments||[]).forEach(p=>{if(!p.destination||!validPaymentDestination(p)||p.status==='Anulado'||p.amount<=0)return;flowRecords.push({sourceProject:i,account:p.destination,type:'Entrada',amount:p.amount,date:p.date,concept:(p.kind==='advance'?'Anticipo de proyecto · ':'Pago de proyecto · ')+pr.name,notes:projectClientName(pr)+' · '+p.method+(p.origin?' · Origen: '+p.origin:'')+(p.observations?' · '+p.observations:'')})});syncProjectCommissionFlow(i)}
function projectPayment(i){const pr=projectRecords[i];if(!pr)return;if(!clients[pr.clientId])return toast('Primero vincula el proyecto a un cliente con Editar');const pending=Math.max(0,pr.amount-pr.paid);if(!pending)return toast('Este proyecto ya está liquidado');openmodal(modalhead('Registrar pago · '+esc(pr.name))+`<form onsubmit="saveProjectPayment(event,${i})"><p>${esc(projectClientName(pr))} · Saldo: <strong>${paymentMoney(pending)}</strong></p>${paymentFields(pending,{},true)}<button class="primary wide">Guardar pago y entrada en Flujo</button></form>`)}
function applyProjectPayment(i,p){const pr=projectRecords[i];if(!pr||!clients[pr.clientId]||!validPayment(p,pr.amount-pr.paid)||!validPaymentDestination(p))return false;pr.paid=Math.round((pr.paid+p.amount)*100)/100;(pr.payments??=[]).push(p);syncProjectFlow(i);return true}
function saveProjectPayment(e,i){e.preventDefault();if(!applyProjectPayment(i,readPayment(new FormData(e.target))))return toast('Revisa el pago, cliente y cuenta destino; los pagos en efectivo van a Efectivo');closemodal();render();toast('Pago registrado · Entrada en Flujo e historial actualizados')}
function toggleclient(i){openmodal(modalhead(clients[i].active?'Dar de baja cliente':'Reactivar cliente')+`<p>${esc(clients[i].name)}</p><p class="hint">Esta demostración aplica el cambio al mes completo. El historial y los saldos pendientes se conservan. La selección de fecha y prorrateo se implementará en la versión operativa.</p><button class="primary wide" onclick="clients[${i}].active=!clients[${i}].active;closemodal();render();toast('Cliente actualizado · Proyección y nómina recalculadas')">${clients[i].active?'Dar de baja en la demo':'Reactivar en la demo'}</button>`)}
const paymentMoney=n=>'$'+n.toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
let peopleRoleOrder='',peopleIncomeOrder='',peopleArchiveView=false;

function personInPayroll(p,period=selectedPeriod()){return Boolean(p)&&(!p.deletedAt||period<=p.deletedAt.slice(0,7))}
function personBaseForPeriod(p,period=selectedPeriod()){return personInPayroll(p,period)?p.base:0}
const peopleEditIcon='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg>';
const peopleTrashIcon='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/></svg>';
function personActions(p,k){return `<div class="personactions personmanagement">${p.deletedAt?`<button onclick="restorePerson(${k})" aria-label="Restaurar a ${esc(p.name)}">↶ Restaurar</button>`:`<div class="personeditrow"><button class="primary" onclick="editperson(${k})" aria-label="Editar a ${esc(p.name)}">${peopleEditIcon} Editar</button><button class="persondelete" onclick="deletePersonDialog(${k})" aria-label="Eliminar a ${esc(p.name)}" title="Eliminar colaborador">${peopleTrashIcon}</button></div>`}<button onclick="persondetail(${k})">Ver desglose ↗</button>${p.deletedAt?'':`<button onclick="personalDashboard(${k})">Vista personal ↗</button><button onclick="showPersonInvite(${k})">Invitar / activación</button>`}</div>`}
function deletePersonDialog(k){const p=people[k];if(!p||p.deletedAt)return;const brands=clients.filter(c=>c.active&&c.team.includes(k));openmodal(modalhead('Eliminar colaborador')+`<p><strong>${esc(p.name)}</strong> · ${esc(p.role)}</p><p>Se moverá a Eliminados. Puedes restaurarlo desde esa pestaña. Sus pagos, comisiones y referencias en clientes y proyectos se conservarán.</p><p>La baja se aplica hoy. Los importes del mes de baja se conservan; desde el mes siguiente deja de generar sueldo fijo y comisiones de igualas. Las comisiones de proyectos ya acordadas siguen registradas.</p>${brands.length?`<p class="hint">Tiene ${brands.length} marca(s) asignada(s): ${brands.map(c=>esc(c.name)).join(', ')}. Reasigna su trabajo desde Clientes → Editar.</p>`:''}<div class="formactions"><button onclick="closemodal()">Cancelar</button><button class="primary" onclick="archivePerson(${k})">Eliminar colaborador</button></div>`)}
function archivePerson(k){const p=people[k];if(!p||p.deletedAt)return false;p.deletedAt=mexicoDay();p.accessBeforeDelete=p.accessActive!==false;p.accessActive=false;closemodal();render();toast('Colaborador movido a Eliminados · Historial conservado');return true}
function restorePerson(k){const p=people[k];if(!p?.deletedAt)return false;openmodal(modalhead('Restaurar colaborador')+`<p>¿Restaurar a <strong>${esc(p.name)}</strong> con su puesto y sueldo guardados?</p><p class="hint">Volverá al listado y se reactivarán los cálculos de sueldo e igualas de sus marcas asignadas.</p><div class="formactions"><button onclick="closemodal()">Cancelar</button><button class="primary" onclick="applyRestorePerson(${k})">Restaurar colaborador</button></div>`)}
function applyRestorePerson(k){const p=people[k];if(!p?.deletedAt)return false;p.accessActive=p.accessBeforeDelete!==false;delete p.deletedAt;delete p.accessBeforeDelete;closemodal();render();toast('Colaborador restaurado · Guardando cambios');return true}

function orderedPeople(){return people.map((p,k)=>({p,k})).filter(({p})=>Boolean(p.deletedAt)===peopleArchiveView).sort((a,b)=>{const role=peopleRoleOrder?Number(b.p.role===peopleRoleOrder)-Number(a.p.role===peopleRoleOrder):0;if(role)return role;if(peopleIncomeOrder)return (personEarnings(a.k).total-personEarnings(b.k).total)*(peopleIncomeOrder==='asc'?1:-1);return a.k-b.k})}
function paySchedule(k){const e=personEarnings(k),regular=Math.round((e.base+e.retainers)*100),first=Math.round(regular/2)/100,last=Math.min(30,new Date(+year,+month,0).getDate());return {...e,first,second:regular/100-first,last}}
let payrollStatuses={},payrollFilter='Todas';
function quincenaRecord(k,q,period=selectedPeriod()){return payrollStatuses[period]?.[k]?.[q]||null}
function quincenaState(k,q){const e=paySchedule(k),amount=q===1?e.first:e.second,record=quincenaRecord(k,q),paid=record?.paid?record.amount:0;return {amount,paid,pending:Math.max(0,Math.round((amount-paid)*100)/100),status:amount>0&&paid>=amount?'Pagado':'Pendiente',day:q===1?15:e.last}}
function setQuincenaStatus(k,q,value){if(!people[k]||![1,2].includes(q)||!['Pendiente','Pagado'].includes(value))return;const e=quincenaState(k,q),period=selectedPeriod();if(value==='Pagado'){render();if(e.amount>0)quincenaPaymentForm(k,q,period);return}payrollStatuses[period]??={};payrollStatuses[period][k]??={};payrollStatuses[period][k][q]={...quincenaRecord(k,q),paid:false,updatedAt:new Date().toISOString()};syncPayrollFlow(k,q,period);render();toast('Quincena pendiente · Salida de Flujo actualizada')}
function quincenaColumn(k,q){const state=quincenaState(k,q);return `<td class="quincenacol"><strong>${paymentMoney(state.amount)}</strong><small>Día ${state.day}</small><select aria-label="Quincena ${q} de ${esc(people[k].name)}" onchange="setQuincenaStatus(${k},${q},this.value)" ${state.amount<=0?'disabled':''}><option ${state.status==='Pendiente'?'selected':''}>Pendiente</option><option ${state.status==='Pagado'?'selected':''}>Pagado</option></select>${quincenaRecord(k,q)?.paid?`<button class="payrollsource" onclick="quincenaPaymentForm(${k},${q},'${selectedPeriod()}')">${esc(flowAccountName(quincenaRecord(k,q).source)||'Completar cuenta')} · Editar</button>`:''}${state.paid>0&&state.pending>0?`<small>Pagado antes del ajuste: ${paymentMoney(state.paid)}</small>`:''}</td>`}
function payrollEntries(){return people.flatMap((p,k)=>[1,2].map(q=>({person:k,name:p.name,role:p.role,q,...quincenaState(k,q)}))).filter(r=>r.amount>0||r.paid>0)}
function payrollPaymentTotals(q=null){return payrollEntries().filter(r=>q===null||r.q===q).reduce((sum,r)=>({scheduled:sum.scheduled+r.amount,paid:sum.paid+r.paid,pending:sum.pending+r.pending}),{scheduled:0,paid:0,pending:0})}
function financePayroll(){const entries=people.map((p,k)=>({p,k,e:paySchedule(k),q1:quincenaState(k,1),q2:quincenaState(k,2)})).filter(r=>(r.e.first+r.e.second>0)&& (payrollFilter==='Todas'||[r.q1,r.q2].some(q=>payrollFilter==='Pagadas'?q.status==='Pagado':q.status!=='Pagado'))),sum=q=>entries.reduce((n,r)=>n+(q===1?r.e.first:q===2?r.e.second:r.e.first+r.e.second),0);return `<section class="financepayroll"><div class="sectionline"><h2>Nómina</h2><button onclick="go('Colaboradores')">Ver colaboradores ↗</button></div><div class="card payrollgrand"><span class="label">Total de la nómina mensual</span><div class="value">${paymentMoney(totals().pay)}</div><small>Sueldos fijos + comisiones de igualas + comisiones de proyectos.</small></div><div class="quincenas financequincenas">${[1,2].map(q=>{const t=payrollPaymentTotals(q);return `<section class="card" aria-label="Resumen quincena ${q}"><div class="cardline"><h3>Quincena ${q}</h3><span class="pill">Día ${q===1?15:Math.min(30,new Date(+year,+month,0).getDate())}</span></div><div class="financenumber"><span>Total de la quincena</span><strong>${paymentMoney(t.scheduled)}</strong></div><div class="financenumber"><span>Pagadas</span><strong>${paymentMoney(t.paid)}</strong></div><div class="financenumber"><span>Por pagar</span><strong>${paymentMoney(t.pending)}</strong></div></section>`}).join('')}</div><div class="toolbar"><div class="tabs">${['Todas','Pagadas','Por pagar'].map(f=>`<button class="${payrollFilter===f?'selected':''}" onclick="payrollFilter='${f}';render()">${f}</button>`).join('')}</div><span class="hint">${payrollFilter==='Todas'?'Una fila por colaborador':'Colaboradores con al menos una quincena en este estado'}</span></div><div class="tablewrap"><table class="financepayrolltable"><thead><tr><th>COLABORADOR</th><th>TOTAL MENSUAL<small>Sueldo fijo + igualas</small></th><th>QUINCENA 1<small>Primera mitad · Día 15</small></th><th>QUINCENA 2<small>Segunda mitad · Día ${Math.min(30,new Date(+year,+month,0).getDate())}</small></th></tr></thead><tbody>${entries.map(({p,k,e})=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></td><td class="payrollmonthly"><strong>${paymentMoney(e.first+e.second)}</strong></td>${quincenaColumn(k,1)}${quincenaColumn(k,2)}</tr>`).join('')}</tbody><tfoot><tr><td>Total de esta vista</td><td>${paymentMoney(sum(0))}</td><td>${paymentMoney(sum(1))}</td><td>${paymentMoney(sum(2))}</td></tr></tfoot></table>${!entries.length?'<div class="empty">No hay colaboradores con quincenas en este estado.</div>':''}</div><p class="hint">Cambia Pagado o Pendiente directamente en cada quincena. Se actualiza también en Colaboradores. El total mensual de esta tabla se divide en dos; las comisiones de proyectos se muestran aparte porque se pagan al recibir el cobro del cliente.</p>${financeProjectCommissions()}</section>`}
function payroll(){return heading('Colaboradores','Personas, ingresos por igualas y proyectos, y permisos de acceso.',`${monthselect()}<button class="primary" onclick="newperson()">+ Dar de alta colaborador</button>`)+`<div class="sectionline"><span class="hint">${names[+month-1]} ${year} · Importes mensuales</span></div><div class="costs"><div class="card"><div class="label">Nómina mensual</div><div class="value">${money(totals().pay)}</div></div><div class="card"><div class="label">Colaboradores</div><div class="value">${people.filter(p=>!p.deletedAt).length}</div></div><div class="card"><div class="label">Quincena 1 · Fijo + igualas</div><div class="value">${money(people.reduce((n,p,k)=>n+paySchedule(k).first,0))}</div></div></div><div class="toolbar"><div class="tabs"><button class="${!peopleArchiveView?'selected':''}" onclick="peopleArchiveView=false;render()">Colaboradores (${people.filter(p=>!p.deletedAt).length})</button><button class="${peopleArchiveView?'selected':''}" onclick="peopleArchiveView=true;render()">Eliminados (${people.filter(p=>p.deletedAt).length})</button></div><span class="hint">Edita nombre, correo, puesto, sueldo y permisos con el lápiz.</span></div><div class="tablewrap"><table class="peoplemanagementtable"><thead><tr><th>COLABORADOR</th><th><label class="sortlabel">PUESTO<select aria-label="Ordenar por puesto" onchange="peopleRoleOrder=this.value;peopleIncomeOrder='';render()"><option value="">Orden original</option>${collaboratorRoles.map(r=>`<option value="${r}" ${peopleRoleOrder===r?'selected':''}>${r} primero</option>`).join('')}</select></label></th><th>MARCAS ACTIVAS</th><th>SUELDO FIJO</th><th>COMISIONES IGUALAS</th><th>COMISIONES PROYECTOS</th><th><label class="sortlabel">TOTAL MENSUAL<select aria-label="Ordenar por ingreso mensual" onchange="peopleIncomeOrder=this.value;peopleRoleOrder='';render()"><option value="">Orden original</option><option value="desc" ${peopleIncomeOrder==='desc'?'selected':''}>Mayor a menor ↓</option><option value="asc" ${peopleIncomeOrder==='asc'?'selected':''}>Menor a mayor ↑</option></select></label></th><th>QUINCENA 1</th><th>QUINCENA 2</th><th>PERMISOS / ACCESO</th><th>ACCIONES</th></tr></thead><tbody>${orderedPeople().map(({p,k})=>{const e=personEarnings(k);return `<tr><td>${esc(p.name)}<small>${esc(p.email||'Sin correo registrado')}</small></td><td>${esc(p.role)}</td><td>${e.brands.length}</td><td>${money(e.base)}</td><td>${money(e.retainers)}</td><td>${money(e.projectPay)}</td><td>${money(e.total)}</td>${quincenaColumn(k,1)}${quincenaColumn(k,2)}<td><span class="pill">${p.deletedAt?'Eliminado':p.accessActive===false?'Suspendido':'Activo'}</span>${p.deletedAt?`<small>Baja: ${esc(p.deletedAt)}</small>`:''}<div class="permissionchips">${personPermissionChips(p)}</div></td><td>${personActions(p,k)}</td></tr>`}).join('')}</tbody></table></div><p class="hint">Comisiones igualas y Comisiones proyectos muestran únicamente el pago asignado a esa persona, no el precio que paga el cliente. Las asignaciones se configuran en Proyectos → Editar. Eliminar conserva el historial y los importes del mes de baja; desde el mes siguiente deja de generar sueldo fijo y comisiones de igualas. Las comisiones de proyectos acordadas se conservan.</p>${orderedPeople().length?'':'<div class="empty">No hay colaboradores en esta vista.</div>'}`}
function personPermissionChips(p){const perms=personPermissions(p);return permissionTabs.filter(t=>perms[t.key]).map(t=>`<span class="pill">${t.label}</span>`).join('')||'<small>Sin pestañas habilitadas</small>'}
function earningsBreakdown(k){const e=paySchedule(k);return `<div class="sectionline"><h3>Pagos quincenales</h3></div><p class="hint">Sueldo fijo + comisiones de igualas. Los proyectos se pagan por separado al recibir el cobro del cliente.</p><div class="quincenas">${[[1,15,e.first],[2,e.last,e.second]].map(([q,day,total])=>`<div class="card"><div class="label">Quincena ${q} · ${day} de ${names[+month-1]}</div><span class="pill">${quincenaState(k,q).status}</span><div class="value">${paymentMoney(total)}</div><small>Sueldo fijo: ${paymentMoney(q===1?Math.round(e.base*100/2)/100:e.base-Math.round(e.base*100/2)/100)}</small><small>Igualas: ${paymentMoney(total-(q===1?Math.round(e.base*100/2)/100:e.base-Math.round(e.base*100/2)/100))}</small></div>`).join('')}</div><div class="sectionline"><h3>Comisiones igualas</h3><strong>${paymentMoney(e.retainers)}</strong></div><table><thead><tr><th>MARCA</th><th>COMISIÓN MENSUAL</th></tr></thead><tbody>${e.brands.map(c=>`<tr><td>${esc(c.name)}</td><td>${paymentMoney(c.comm[c.team.indexOf(k)])}</td></tr>`).join('')||'<tr><td colspan="2">Sin marcas asignadas.</td></tr>'}</tbody></table><div class="sectionline"><h3>Comisiones proyectos</h3><strong>${paymentMoney(e.projectPay)}</strong></div><p class="hint">Las comisiones de proyectos se dividen en anticipo y entrega, con estados independientes de las quincenas.</p><table><thead><tr><th>PROYECTO</th><th>COMISIÓN TOTAL</th><th>ANTICIPO</th><th>ENTREGA</th></tr></thead><tbody>${e.projects.map(pr=>`<tr><td>${esc(pr.name)}<small>${esc(pr.client)}</small></td><td>${paymentMoney(pr.amount)}</td><td>${commissionPartText(pr,'advance')}</td><td>${commissionPartText(pr,'delivery')}</td></tr>`).join('')||'<tr><td colspan="4">Sin comisiones de proyectos este mes.</td></tr>'}</tbody></table>`}
function persondetail(k){const p=people[k],e=personEarnings(k);openmodal(modalhead(`<span class="collaborator-name">${esc(p.name)}</span>`)+`<div class="cardline"><p class="hint">${esc(p.role)} · ${names[+month-1]} ${year}</p><button onclick="downloadEarnings(${k})">Descargar imagen ↓</button></div><div class="sales earningshero"><div><div class="label">TOTAL ACUMULADO DEL MES</div><div class="value">${paymentMoney(e.total)}</div><small>Sueldo fijo ${paymentMoney(e.base)} + Comisiones igualas ${paymentMoney(e.retainers)} + Comisiones proyectos ${paymentMoney(e.projectPay)}</small></div></div>${earningsBreakdown(k)}<p class="hint">Desglose informativo de importes asignados; no es comprobante de pago.</p>`)}
async function downloadEarnings(k){
 try{await document.fonts.ready;const p=people[k],e=paySchedule(k),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1280+(e.brands.length+e.projects.length)*64;const ctx=canvas.getContext('2d');ctx.fillStyle='#F8F5EB';ctx.fillRect(0,0,canvas.width,canvas.height);let y=70;
 const text=(str,size=26,color='#20201e',weight='normal',x=64)=>{ctx.font=weight+' '+size+'px H, sans-serif';ctx.fillStyle=color;ctx.fillText(str,x,y,x===64?900:180);};
 const line=(label,value)=>{text(label,24);ctx.textAlign='right';text(value,26,'#20201e','normal',1016);ctx.textAlign='left';y+=64;};
 text('CLANDESTINO STUDIO',26,'#20201e','bold');y+=64;text(p.name,64,'#20201e','bold');y+=52;text(p.role+' · '+names[+month-1]+' '+year,24);y+=60;
 ctx.fillStyle='#20201e';ctx.fillRect(64,y,952,160);y+=45;text('TOTAL ACUMULADO DEL MES',22,'#F8F5EB');y+=72;text(paymentMoney(e.total),58,'#F8F5EB');y+=84;
 line('Sueldo fijo',paymentMoney(e.base));line('Comisiones igualas',paymentMoney(e.retainers));line('Comisiones proyectos',paymentMoney(e.projectPay));y+=10;text('PAGOS QUINCENALES · FIJO + IGUALAS',24,'#20201e','bold');y+=55;
 line('Quincena 1 · 15 de '+names[+month-1]+' · '+quincenaState(k,1).status,paymentMoney(e.first));line('Quincena 2 · '+e.last+' de '+names[+month-1]+' · '+quincenaState(k,2).status,paymentMoney(e.second));y+=12;text('COMISIONES IGUALAS',24,'#20201e','bold');y+=55;
 if(!e.brands.length){text('Sin marcas asignadas',24);y+=64;}else e.brands.forEach(c=>line(c.name,paymentMoney(c.comm[c.team.indexOf(k)])));
 y+=10;text('COMISIONES PROYECTOS',24,'#20201e','bold');y+=55;if(!e.projects.length){text('Sin proyectos asignados',24);y+=64;}else e.projects.forEach(pr=>line(pr.name,paymentMoney(pr.amount)));
 text('Proyectos: pago al recibir el cobro del cliente; fuera de quincenas.',22);y+=42;text('Desglose informativo · No acredita un pago realizado.',22);y+=36;text('Datos de ejemplo · Prototipo Clandestino Studio',20,'#666');
 canvas.toBlob(blob=>{if(!blob)return toast('No se pudo generar la imagen');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Desglose-'+p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-')+'-'+selectedPeriod()+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Imagen descargada para compartir')},'image/png');
 }catch(err){toast('No se pudo generar la imagen. Intenta de nuevo.')}
}
function personalDashboard(k){const p=people[k],e=personEarnings(k),perms=personPermissions(p);openmodal(modalhead(`<span class="collaborator-name">${esc(p.name)}</span>`)+`<p class="hint">Simulación para Dirección · No es una sesión real del colaborador.</p><button onclick="showNotifications('person:${k}')">Mis avisos · ${unreadNotifications('person:'+k)}</button>${p.accessActive===false?'<div class="empty">Acceso suspendido. Esta persona no podrá ingresar cuando se conecten los usuarios reales.</div>':`<div class="permissionchips">${personPermissionChips(p)}</div><div class="sectionline"><div><div class="eyebrow">${esc(p.role)}</div><h2>Mi cuenta · ${names[+month-1]} ${year}</h2></div></div>${perms.account?`<div class="earningscards">${[['Sueldo fijo',e.base],['Comisiones igualas',e.retainers],['Comisiones proyectos',e.projectPay],['Mi acumulado',e.total]].map(([l,v])=>`<div class="card"><div class="label">${l}</div><div class="value">${money(v)}</div></div>`).join('')}</div>${earningsBreakdown(k)}`:'<p class="hint">Mi cuenta no está habilitada para esta persona. Dirección puede activarla en Editar y permisos.</p>'}${perms.content?`<div class="sectionline"><h3>Mis marcas · Contenido</h3></div><div class="personalbrands">${e.brands.map(c=>`<div class="card"><strong>${esc(c.name)}</strong><small>Contenido del mes</small></div>`).join('')||'<p class="hint">Sin marcas activas asignadas.</p>'}</div>`:''}`}`)}
const permissionTabs=[{key:'calendar',label:'Calendario',note:'Agenda de sesiones, juntas y citas.'},{key:'content',label:'Contenido',note:'Solo sus marcas asignadas.'},{key:'account',label:'Mi cuenta',note:'Solo su sueldo, comisiones y acumulado.'},{key:'home',label:'Vista General',note:'Resumen y números de todo el negocio.'},{key:'clients',label:'Clientes',note:'Listado y datos de los clientes.'},{key:'retainers',label:'Igualas',note:'Igualas y cobros de clientes.'},{key:'projects',label:'Proyectos',note:'Listado, importes y avances de proyectos.'},{key:'people',label:'Colaboradores',note:'Consulta del equipo y nómina general. No permite otorgar permisos.'},{key:'expenses',label:'Gastos',note:'Registro y edición de gastos fijos, variables e inversión.'},{key:'flow',label:'Flujo',note:'Movimientos manuales de efectivo y cuentas bancarias.'},{key:'finance',label:'Finanzas',note:'Cuentas por cobrar de igualas y proyectos.'}];
function personPermissions(p){return Object.fromEntries(permissionTabs.map(t=>[t.key,p.permissions?.[t.key]??['content','account'].includes(t.key)]))}
function personPermissionSummary(p){const access=personPermissions(p),labels=permissionTabs.filter(t=>access[t.key]).map(t=>t.label);return labels.length?esc(labels.join(' · ')):'Sin pestañas habilitadas'}
function newperson(){personform()}
function editperson(k){if(people[k]&&!people[k].deletedAt)personform(k)}
function personform(k=null){
 const editing=k!==null,p=editing?people[k]:{name:'',role:collaboratorRoles[0],base:0,email:'',accessActive:true},perms=personPermissions(p);
 openmodal(modalhead(editing?'Editar colaborador y permisos':'Dar de alta colaborador')+`<form onsubmit="saveperson(event,${editing?k:'null'})"><div class="formgrid"><label>Nombre<input name="name" value="${esc(p.name)}" maxlength="120" required></label><label>Correo de acceso<input name="email" type="email" value="${esc(p.email||'')}" placeholder="nombre@correo.com"><small>Puedes dejarlo pendiente mientras definimos la estructura.</small></label><label>Puesto<select name="role" style="width:100%;margin-top:7px">${collaboratorRoles.map(r=>`<option ${p.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>Sueldo base mensual ($)<input name="base" type="number" min="0" step="0.01" value="${p.base}" required><small>Deja $0 si trabaja únicamente por comisiones.</small></label><label>Estado del acceso<select name="accessActive" style="width:100%;margin-top:7px"><option value="true" ${p.accessActive!==false?'selected':''}>Activo</option><option value="false" ${p.accessActive===false?'selected':''}>Suspendido</option></select></label><div class="profilefixed"><span class="label">Perfil</span><strong>Colaborador</strong><small>Selecciona sus marcas de acceso abajo. El equipo se administra también en Clientes.</small></div></div>${personBrandAccessPanel(k,p)}<div class="sectionline"><div><div class="eyebrow">CONFIGURACIÓN DE DIRECCIÓN</div><h2>Pestañas que puede ver</h2></div></div><p class="hint">El acceso de colaborador habilitado en esta versión es Contenido + un perfil básico de Mi cuenta. Las demás pestañas se conservan como configuración pendiente; no dan acceso a los datos de Dirección.</p><div class="permissiongrid">${permissionTabs.map(t=>`<label class="permissionitem"><input name="permission_${t.key}" type="checkbox" ${perms[t.key]?'checked':''}><span><strong>${t.label}</strong><small>${t.note}</small></span></label>`).join('')}</div><div class="permissionowner"><strong>Administrar usuarios y permisos</strong><span class="pill">Exclusivo Dirección</span><small>Los colaboradores no pueden otorgar acceso ni modificar permisos, aunque tengan habilitada la pestaña Colaboradores.</small></div><p class="hint">Los datos y permisos se guardan en Supabase. La invitación se envía mediante el botón de activación, cuando el correo y el acceso externo estén configurados. No se crea ninguna contraseña aquí.</p><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">${editing?'Guardar cambios':'Guardar colaborador'}</button></div></form>`)
}
function saveperson(e,k=null){
 e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim(),role=f.get('role'),base=Number(f.get('base'));
 if(!name||!collaboratorRoles.includes(role)||!Number.isFinite(base)||base<0||(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))){toast('Revisa el nombre, correo, puesto y sueldo base');return}
 if(email&&people.some((p,i)=>i!==k&&(p.email||'').toLowerCase()===email.toLowerCase())){toast('Ese correo ya está asignado a otro colaborador');return}
 const permissions=Object.fromEntries(permissionTabs.map(t=>[t.key,f.get('permission_'+t.key)==='on'])),brandAccess=[...new Set(f.getAll('brandAccess').map(Number))];if(brandAccess.some(i=>!Number.isInteger(i)||!clients[i]))return toast('Revisa las marcas seleccionadas');const fields={name,email,role,base,accessActive:f.get('accessActive')==='true',permissions,brandAccess};
 const sendInvite=f.get('sendInvite')==='on';if(k===null){people.push(fields);k=people.length-1}else{if(!people[k]||people[k].deletedAt)return;Object.assign(people[k],fields)}
 closemodal();render();toast('Colaborador guardado · Revisa su acceso e invitación');if(sendInvite)showPersonInvite(k)
}
const contentGroups={posts:{title:'Feed',single:'Publicación',ratio:'1080 × 1350',portrait:false},stories:{title:'Stories',single:'Story',ratio:'1080 × 1920',portrait:true},adsStories:{title:'AD STORIE',single:'AD STORIE',ratio:'1080 × 1920',portrait:true},adsPosts:{title:'IMAGEN AD',single:'IMAGEN AD',ratio:'1080 × 1350',portrait:false}};
function blankPiece(){return {copy:'',photo:'',design:'',image:'',images:[],inspiration:'',type:'Imagen'}}
function contentData(i=selected){const key=i+'-'+year+'-'+String(month).padStart(2,'0');if(!contents[key])contents[key]={objective:'',production:'',final:'',stage:0,posts:Array.from({length:15},blankPiece),completed:{}};const d=contents[key];d.completed??={};for(const [group,n] of [['stories',3],['adsStories',1],['adsPosts',1]])if(!Array.isArray(d[group]))d[group]=Array.from({length:n},blankPiece);return d}
function data(){return contentData(selected)}
function allPieces(d){return Object.keys(contentGroups).flatMap(group=>d[group]||[])}
function pieceTiles(group){const cfg=contentGroups[group];return `<div class="feed ${cfg.portrait?'storyfeed':''}">${data()[group].map((p,i)=>`<div class="posttile ${cfg.portrait?'storytile':''}"><button class="post" onclick="editpost(${i},'${group}')"><span class="num">${String(i+1).padStart(2,'0')} · ${esc(group.startsWith('ads')?cfg.single:(p.type||'Imagen'))}</span>${p.type==='Reel'&&p.video?'<span class="videobadge">▶ Video</span>':''}${p.type==='Carrusel'?`<span class="carouselcount">▣ ${p.images?.length||1} imágenes</span>`:''}${p.image?`<img src="${p.image}" alt="${cfg.single} ${i+1} · ${esc(p.type||'Imagen')}" loading="lazy">`:`<span class="plus">+</span><small>${p.copy?'Editar '+(group.startsWith('ads')?cfg.single:cfg.single.toLowerCase()):'Crear '+(group.startsWith('ads')?cfg.single:cfg.single.toLowerCase())}</small>`}</button><button class="postdelete" type="button" aria-label="Borrar ${(group.startsWith('ads')?cfg.single:cfg.single.toLowerCase())} ${i+1}" title="Borrar ${(group.startsWith('ads')?cfg.single:cfg.single.toLowerCase())}" onclick="requestDeletePost(${i},'${group}')"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div>`).join('')}</div>${deletedPost&&deletedPost.doc===data()&&deletedPost.group===group?'<div class="postundo" role="status">Pieza borrada.<button onclick="undoDeletePost()">Deshacer</button></div>':''}<button class="wide" onclick="addPiece('${group}')">+ Agregar ${(group.startsWith('ads')?cfg.single:cfg.single.toLowerCase())}</button>`}
function addPiece(group){if(!contentGroups[group])return;data()[group].push(blankPiece());render()}
function extraContent(){return `<section class="contentsection" aria-label="Stories"><div class="sectionline"><h2>Stories <span class="hint">/ ${data().stories.length} ${data().stories.length===1?'pieza':'piezas'}</span></h2><span class="hint">1080 × 1920</span></div>${pieceTiles('stories')}</section><section class="contentsection" aria-label="Ads"><div class="sectionline"><div><div class="eyebrow">CONTENIDO PARA PAUTA</div><h2>Ads</h2></div><span class="hint">Instrucciones y vistas previas</span></div><div class="sectionline"><h3>AD STORIE <span class="hint">/ ${data().adsStories.length} ${data().adsStories.length===1?'pieza':'piezas'}</span></h3><span class="hint">1080 × 1920</span></div>${pieceTiles('adsStories')}<div class="sectionline"><h3>IMAGEN AD <span class="hint">/ ${data().adsPosts.length} ${data().adsPosts.length===1?'pieza':'piezas'}</span></h3><span class="hint">1080 × 1350</span></div>${pieceTiles('adsPosts')}</section>`}
let contentTab='Marcas',trackingFilter='Todas';
const stages=['En Marketing','En fotografía / video','En diseño','Revisión · Dirección y Marketing','Listo para cliente','En revisión del cliente','Aprobado'];
const stageButtons=['Marcar listo · Marketing','Marcar listo · Fotografía / Video','Listo para revisión · Diseño','Listo para mostrar al cliente · Dirección','Marcar enviado a cliente','Marcar aprobado por cliente','Contenido aprobado'];
function activeContentBrands(){return clients.map((c,i)=>({c,i})).filter(({c})=>c.active&&c.fee>0&&c.team.length)}
function mexicoDay(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function materialDeadline(y=+year,m=+month){return new Date(Date.UTC(y,m-1,25)).toISOString().slice(0,10)}
function deadlineLabel(){const d=materialDeadline();return '25 de '+names[Number(d.slice(5,7))-1]+' '+d.slice(0,4)}
function lateContent(d,today=mexicoDay()){return d.stage<3&&!d.reviewReadyAt&&!d.readyAt&&today>materialDeadline()}
function deliveryLabel(d){return lateContent(d)?'Atrasado':''}
function openBrand(i){selected=i;page='Marca';render()}
function openTracking(filter='Todas'){page='Contenido';contentTab='Seguimiento';trackingFilter=filter;render()}
function trackingCounts(){const brands=activeContentBrands(),late=brands.filter(({i})=>lateContent(contentData(i))).length;return [...stages.map((label,stage)=>({label,value:brands.filter(({i})=>contentData(i).stage===stage).length,filter:String(stage)})),...(late?[{label:'Atrasadas',value:late,filter:'Atrasadas'}]:[])]}
function contentOverview(){return `<div class="sectionline"><h2>Avance de contenido</h2><button onclick="openTracking()">Ver seguimiento ↗</button></div><p class="hint">Contenido de ${names[+month-1]} ${year} · Material listo: ${deadlineLabel()}</p><div class="trackingcounts compact">${trackingCounts().map(t=>`<button class="card" onclick="openTracking('${t.filter}')"><span class="label">${t.label}</span><strong>${t.value}</strong></button>`).join('')}</div>`}
function contentTimeline(c,d){return `<ol class="contenttimeline">${['Marketing','Fotografía / Video','Diseño','Revisión de Dirección y Marketing','Listo para mostrar al cliente','Revisión del cliente','Aprobado'].map((label,i)=>{const person=i<3?people[c.team[i]]?.name:i===3?'Dirección · '+(people[c.team[0]]?.name||'Marketing'):'';return `<li class="${i<d.stage?'done':i===d.stage?'current':'waiting'}"><span class="timelinepoint" aria-hidden="true">${i<d.stage?'✓':i+1}</span><div><strong>${label}</strong><small>${i<d.stage?'Listo':i===d.stage?(i===6?'Aprobado':'En proceso'):'Pendiente'}${person?' · '+esc(person):''}</small></div></li>`}).join('')}</ol>`}
function trackingCell(d,j,c){const done=j<4?d.stage>j:d.stage===6,current=j<4?d.stage===j:d.stage>=4&&d.stage<6,person=j<3?people[c.team[j]]?.name:j===3?'Roy / Marketing':'Cliente',label=j===4?(d.stage===6?'Aprobado':d.stage===5?'En revisión':d.stage===4?'Listo para enviar':'Pendiente'):done?'✓ Listo':current?(d.adjustments&&j===2?'Ajustes':'En proceso'):'Pendiente';return `<td><div class="trackphase ${done?'done':current?'current':'pending'}"><strong>${label}</strong><small>${esc(person||'Sin asignar')}</small></div></td>`}
function trackingView(){const list=activeContentBrands().filter(({i})=>trackingFilter==='Todas'||(trackingFilter==='Atrasadas'?lateContent(contentData(i)):contentData(i).stage===Number(trackingFilter)));return `<div class="deadlinebanner"><div><span class="label">FECHA LÍMITE · LISTO PARA REVISIÓN</span><strong>${deadlineLabel()}</strong><small>Contenido de ${names[+month-1]} ${year}. Material listo para revisión interna a más tardar el día 25.</small></div><span class="pill">Una fecha para todas las marcas</span></div><div class="trackingcounts">${trackingCounts().map(t=>`<button class="card ${trackingFilter===t.filter?'chosen':''}" onclick="trackingFilter='${t.filter}';render()"><span class="label">${t.label}</span><strong>${t.value}</strong></button>`).join('')}</div><div class="sectionline"><h2>Avance por marca</h2><button onclick="trackingFilter='Todas';render()">Ver todas</button></div><div class="tablewrap"><table class="trackingtable"><thead><tr><th>MARCA / ENTREGA</th><th>MARKETING</th><th>FOTOGRAFÍA / VIDEO</th><th>DISEÑO</th><th>REVISIÓN INTERNA</th><th>CLIENTE</th><th></th></tr></thead><tbody>${list.map(({c,i})=>{const d=contentData(i);return `<tr><td><strong>${esc(c.name)}</strong>${lateContent(d)?'<span class="pill overduebadge">Atrasado</span>':''}<small>${Math.min(d.stage,4)} de 4 etapas internas listas</small></td>${[0,1,2,3,4].map(j=>trackingCell(d,j,c)).join('')}<td><button onclick="openBrand(${i})">Abrir marca ↗</button></td></tr>`}).join('')}</tbody></table>${!list.length?'<div class="empty">No hay marcas en este estado.</div>':''}</div><p class="hint">Atrasado aparece solo después del día 25 del mes seleccionado si el material aún no está listo para revisión interna. Los ajustes del cliente se identifican aparte cuando el material ya había quedado listo. Los estados y avisos se simulan durante esta sesión.</p>`}
function contentlist(){return heading('Contenido mensual','Avance de cada marca y contenido del mes.',monthselect())+`<div class="toolbar"><div class="tabs">${['Marcas','Seguimiento'].map(t=>`<button class="${contentTab===t?'selected':''}" onclick="contentTab='${t}';render()">${t}</button>`).join('')}</div><span class="hint">${names[+month-1]} ${year}</span></div>`+(contentTab==='Seguimiento'?trackingView():`<div class="sectionline"><h2>Marcas activas</h2><span class="hint">Material listo: ${deadlineLabel()}</span></div><div class="brandcards">${activeContentBrands().map(({c,i})=>{const d=contentData(i);return `<button class="card brandcard" onclick="openBrand(${i})"><div class="brandmark">${String(i+1).padStart(2,'0')} / SOCIAL CONTENT</div><h2>${esc(c.name)}</h2><small>${esc(people[c.team[0]].name)} · Marketing</small><div class="cardline"><span class="pill">${d.adjustments&&d.stage===2?'Ajustes del cliente':stages[d.stage]}</span><span>↗</span></div>${lateContent(d)?'<span class="pill overduebadge">Atrasado</span>':''}</button>`}).join('')}</div>`)}
function contentFlowBar(c,d){return `<section class="horizontalflow" aria-label="Flujo de contenido"><div class="eyebrow">FLUJO DE CONTENIDO</div><div class="timelineviewport">${contentTimeline(c,d)}</div><div class="flowbarfooter"><span class="hint">${allPieces(d).filter(pieceInstructionsComplete).length} de ${allPieces(d).length} piezas con instrucciones completas</span><div class="flowbaractions"><button class="primary" ${d.stage>=6?'disabled':''} onclick="advance()">${stageButtons[d.stage]}</button>${[3,4,5,6].includes(d.stage)?`<button onclick="requestContentChanges()">${d.stage>=4?'Registrar ajustes del cliente':'Solicitar cambios de diseño'}</button>`:''}</div></div></section>`}
function brand(){const c=clients[selected],d=data();return heading(esc(c.name),'Contenido mensual / '+names[+month-1]+' '+year,`<button onclick="go('Contenido')">← Marcas</button>${monthselect()}`)+contentFlowBar(c,d)+`<div class="deadlinebanner"><div><span class="label">LISTO PARA REVISIÓN · ${names[+month-1].toUpperCase()} ${year}</span><strong>${deadlineLabel()}</strong><small>Después: revisión de Dirección y Marketing, y presentación al cliente.</small></div>${lateContent(d)?'<span class="pill overduebadge">Atrasado</span>':''}</div>${clientReviewPanel()}<div class="objective"><div class="cardline"><div class="eyebrow">OBJETIVO DEL MES</div><span class="pill">${stages[d.stage]}</span></div><textarea aria-label="Objetivo del mes" placeholder="Ej. Buen Fin: comunicar el 40% de descuento en toda la tienda." oninput="data().objective=this.value" style="min-height:68px;font-family:G;font-size:24px;border:0;padding:0;margin:4px 0 22px;background:transparent">${esc(d.objective)}</textarea><div class="teamrow">${c.team.map(k=>`<div><span class="label">${people[k].role}</span><div style="margin-top:6px">${esc(people[k].name)}</div></div>`).join('')}<div><span class="label">Revisión final</span><div style="margin-top:6px">Roy Aguado / Marketing</div></div></div></div><div class="links"><div class="card"><label>↗ Material de fotografía / video<input type="url" placeholder="Pegar link de Drive con material editado" value="${esc(d.production)}" oninput="data().production=this.value"></label></div><div class="card"><label>↗ Contenido final de diseño<input type="url" placeholder="Pegar link de Drive con contenido listo" value="${esc(d.final)}" oninput="data().final=this.value"></label></div></div>${generalNotesPanel()}<div class="sectionline"><h2>Parrilla del mes <span class="hint">/ ${d.posts.length} publicaciones</span></h2><span class="hint">1080 × 1350 · Haz clic para editar</span></div><div class="feedlayout contentfullwidth"><div>${pieceTiles('posts')}${extraContent()}</div></div>`}
let pendingPostDelete=null,deletedPost=null,editingPiece=null;
function requestDeletePost(i,group='posts'){
 const doc=data(),post=doc[group]?.[i],cfg=contentGroups[group];if(!post||!cfg)return;pendingPostDelete={doc,post,group};
 openmodal(modalhead('Borrar '+(group.startsWith('ads')?cfg.single:cfg.single.toLowerCase())+' '+String(i+1).padStart(2,'0'))+`<p>Se quitará esta pieza junto con su copy, instrucciones y vista previa.</p><p class="hint">Los archivos de Drive no se borran. Puedes deshacer la última eliminación en esta sesión.</p><div class="formactions"><button onclick="pendingPostDelete=null;closemodal()">Cancelar</button><button class="primary" onclick="confirmDeletePost()">Borrar pieza</button></div>`)
}
function confirmDeletePost(){if(!pendingPostDelete)return;const {doc,post,group}=pendingPostDelete,index=doc[group].indexOf(post);pendingPostDelete=null;if(index<0){closemodal();return}doc[group].splice(index,1);deletedPost={doc,post,group,index};closemodal();render();toast('Pieza borrada · Puedes deshacer desde su sección')}
function undoDeletePost(){if(!deletedPost)return;const {doc,post,index,group}=deletedPost;doc[group].splice(Math.min(index,doc[group].length),0,post);deletedPost=null;render();toast('Pieza restaurada con su contenido')}
function inspirationURL(value){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:''}catch{return ''}}
function carouselDraft(p){const images=p.images?.length?p.images:[p.image||'',''];return images.map((image,j)=>({image,photo:p.slides?.[j]?.photo??(j===0?p.photo||'':''),design:p.slides?.[j]?.design??(j===0?p.design||'':''),inspiration:p.slides?.[j]?.inspiration??(j===0?p.inspiration||'':'')}))}
function emptyCarouselSlide(){return {image:'',photo:'',design:'',inspiration:''}}
function setCarouselInfo(j,field,value){if(editingPiece?.slides[j]&&['photo','design','inspiration'].includes(field))editingPiece.slides[j][field]=value}
function editpost(i,group='posts'){
 const doc=data(),p=doc[group]?.[i],cfg=contentGroups[group];if(!p||!cfg)return;editingPiece={doc,p,group,slides:carouselDraft(p),loading:0};
 openmodal(modalhead(cfg.single+' '+String(i+1).padStart(2,'0'))+`<label class="typeselect">Tipo de contenido<select id="ptype" aria-label="Tipo de contenido" onchange="renderCarouselEditor()">${['Imagen','Carrusel','Reel'].map(t=>`<option ${(p.type||'Imagen')===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="postedit" id="pieceeditorlayout"><div><label>COPY<textarea id="pcopy" placeholder="Escribe el texto de la pieza…">${esc(p.copy)}</textarea></label><div id="singlepreview"><div class="previewempty ${cfg.portrait?'storypreview':''}">${p.type==='Reel'&&p.video?`<video src="${p.video}" poster="${p.image||''}" controls playsinline preload="metadata"></video>`:p.image?`<img src="${p.image}" alt="Vista previa">`:`<span class="hint">Vista previa · ${cfg.ratio}</span>`}</div><label style="margin-top:12px">Subir foto o video<input id="pfile" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" onchange="preparePieceFile(this)"></label><small>Compresión automática: fotos hasta 1920 px y videos hasta 1280 px, con audio. Videos de hasta 250 MB y 5 minutos. Conserva los originales en tu equipo o Drive.</small><p id="mediaprogress" role="status" aria-live="polite">${p.mediaInfo?esc(p.mediaInfo.note)+' · '+StudioMedia.bytes(p.mediaInfo.originalBytes)+' → '+StudioMedia.bytes(p.mediaInfo.bytes):''}</p></div><div id="carouseleditor" hidden></div></div><div id="singleinstructions"><label>Instrucción para fotografía / video<textarea id="pphoto" style="min-height:200px" placeholder="Qué tomas, escenas y material necesitas…">${esc(p.photo)}</textarea></label><label style="margin-top:20px">Instrucción para diseño<textarea id="pdesign" style="min-height:200px" placeholder="Composición, textos en el arte y edición…">${esc(p.design)}</textarea></label><label style="margin-top:20px">Link de inspiración<input id="pinspiration" type="url" placeholder="https://…" value="${esc(p.inspiration||'')}" maxlength="2000"></label><small>Opcional · Pega una referencia de Instagram, Pinterest, TikTok o cualquier sitio.</small>${inspirationURL(p.inspiration)?`<a class="inspirationlink" href="${esc(inspirationURL(p.inspiration))}" target="_blank" rel="noopener noreferrer">Abrir inspiración ↗</a>`:''}</div></div><button class="primary wide" id="savepiece" onclick="savepost()">Guardar pieza</button>`);renderCarouselEditor()
}
function renderCarouselEditor(){const target=editingPiece;if(!target)return;const carousel=$('#ptype').value==='Carrusel';$('#pfile').accept=carousel?'image/jpeg,image/png,image/webp':'image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm';$('#singlepreview').hidden=carousel;$('#singleinstructions').hidden=carousel;$('#pieceeditorlayout').classList.toggle('carouselmode',carousel);const panel=$('#carouseleditor');panel.hidden=!carousel;if(!carousel)return;while(target.slides.length<2)target.slides.push(emptyCarouselSlide());panel.innerHTML=`<div class="sectionline"><h3>Imágenes del carrusel</h3><span class="hint">${target.slides.length} imágenes</span></div><small>Define las instrucciones de cada imagen. Imagen 1 es la portada de la parrilla; el copy de la publicación se escribe arriba.</small><div class="carouselslides detailed">${target.slides.map((slide,j)=>`<section class="carouselslide" aria-label="Imagen ${j+1} del carrusel"><div class="cardline"><h3>Imagen ${j+1}</h3><button type="button" aria-label="Eliminar imagen ${j+1}" onclick="removeCarouselSlide(${j})" ${target.slides.length<=2||target.loading?'disabled':''}>✕</button></div><div class="slidebody"><div><div class="slidepreview ${contentGroups[target.group].portrait?'portrait':''}">${slide.image?`<img src="${slide.image}" alt="Vista previa de imagen ${j+1}">`:'<span>Sin imagen</span>'}</div><label>Cargar imagen ${j+1}<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadCarouselSlide(${j},this)" ${target.loading?'disabled':''}></label></div><div class="slideinstructions"><label>Instrucción para fotografía / video · Imagen ${j+1}<textarea aria-label="Fotografía imagen ${j+1}" placeholder="Tomas, escenas y material para esta imagen…" oninput="setCarouselInfo(${j},'photo',this.value)">${esc(slide.photo||'')}</textarea></label><label>Instrucción para diseño · Imagen ${j+1}<textarea aria-label="Diseño imagen ${j+1}" placeholder="Composición, textos y edición de esta imagen…" oninput="setCarouselInfo(${j},'design',this.value)">${esc(slide.design||'')}</textarea></label><label>Link de inspiración · Imagen ${j+1}<input aria-label="Inspiración imagen ${j+1}" type="url" placeholder="https://…" maxlength="2000" value="${esc(slide.inspiration||'')}" oninput="setCarouselInfo(${j},'inspiration',this.value)"></label>${inspirationURL(slide.inspiration)?`<a class="inspirationlink" href="${esc(inspirationURL(slide.inspiration))}" target="_blank" rel="noopener noreferrer">Abrir inspiración de imagen ${j+1} ↗</a>`:''}</div></div></section>`).join('')}</div><button type="button" class="wide" onclick="addCarouselSlide()" ${target.loading?'disabled':''}>+ Agregar imagen</button><small>Las imágenes se comprimen automáticamente. Conserva los originales en tu equipo o Drive.</small>`}
function addCarouselSlide(){if(!editingPiece||editingPiece.loading)return;editingPiece.slides.push(emptyCarouselSlide());renderCarouselEditor()}
function removeCarouselSlide(j){if(!editingPiece||editingPiece.loading||editingPiece.slides.length<=2)return;editingPiece.slides.splice(j,1);renderCarouselEditor()}
async function uploadCarouselSlide(j,input){const target=editingPiece,slide=target?.slides[j],file=input.files?.[0];if(!target||!slide||!file)return;target.loading++;$('#savepiece').disabled=true;renderCarouselEditor();try{const image=await lightPreview(file,contentGroups[target.group].portrait);if(editingPiece===target&&target.slides.includes(slide))slide.image=image}catch(error){toast(error.message||'No se pudo cargar la imagen')}finally{target.loading--;if(editingPiece===target){$('#savepiece').disabled=target.loading>0;renderCarouselEditor()}}}
function pieceInstructionsComplete(p){return Boolean(p.copy?.trim())&&(p.type==='Carrusel'?Array.isArray(p.slides)&&p.slides.length>=2&&p.slides.every(slide=>slide.photo?.trim()&&slide.design?.trim()):Boolean(p.photo?.trim()&&p.design?.trim()))}
function piecePreviewComplete(p){return p.type==='Carrusel'?Array.isArray(p.images)&&p.images.length>=2&&p.images.every(Boolean):Boolean(p.type==='Reel'?p.video:p.image)}
function preparePieceFile(input){if(!input.files?.[0])return;if(input.files[0].type.startsWith('video/')){$('#ptype').value='Reel';renderCarouselEditor()}$('#mediaprogress').textContent='Se optimizará al guardar. El archivo original no se modifica.'}
async function lightPreview(file,portrait){const compressed=await StudioMedia.compressImage(file);return StudioMedia.dataURL(compressed.blob)}

async function savepost(){
 const target=editingPiece;if(!target)return;if(target.loading)return toast('Espera a que terminen de cargar las imágenes');const {doc,p,group}=target,fields={copy:$('#pcopy').value,photo:$('#pphoto').value,design:$('#pdesign').value,type:$('#ptype').value,inspiration:$('#pinspiration').value.trim()},file=$('#pfile').files[0],button=$('#savepiece');if(fields.type!=='Carrusel'&&fields.inspiration&&!inspirationURL(fields.inspiration))return toast('El link debe comenzar con https:// o http://');if(fields.type==='Carrusel'&&target.slides.some(slide=>slide.inspiration?.trim()&&!inspirationURL(slide.inspiration.trim())))return toast('Revisa los links de inspiración del carrusel');
 target.controller=new AbortController();target.loading=1;button.disabled=true;$('#ptype').disabled=true;$('#pfile').disabled=true;button.textContent='Optimizando…';const progress=$('#mediaprogress'),oldVideo=p.video;let createdURL;
 try{let image=p.image,video=fields.type==='Reel'?(p.video||''):'',mediaInfo=p.mediaInfo;if(fields.type==='Carrusel')image=target.slides[0]?.image||'';else if(file){if(file.type.startsWith('video/')){if(fields.type!=='Reel')throw Error('Selecciona Reel para subir video');progress.textContent='Comprimiendo video… Mantén esta pestaña abierta; tarda aproximadamente lo que dura el video.';const compressed=await StudioMedia.compressVideo(file,{signal:target.controller.signal,onProgress:n=>{if(editingPiece===target){button.textContent='Comprimiendo '+n+'%';progress.textContent='Comprimiendo video: '+n+'%'}}});createdURL=URL.createObjectURL(compressed.blob);video=createdURL;image=compressed.poster;mediaInfo={originalBytes:compressed.originalBytes,bytes:compressed.bytes,saved:compressed.saved,note:compressed.note};}else{const compressed=await StudioMedia.compressImage(file);image=await StudioMedia.dataURL(compressed.blob);mediaInfo={originalBytes:compressed.originalBytes,bytes:compressed.bytes,saved:compressed.saved,note:compressed.note};}}
 if(editingPiece!==target||target.controller.signal.aborted)throw new DOMException('Cancelado','AbortError');if(!doc[group].includes(p))throw Error('Esta pieza ya no está en la parrilla');const images=fields.type==='Carrusel'?target.slides.map(slide=>slide.image):(p.images||[]),slides=fields.type==='Carrusel'?target.slides.map(slide=>({...slide,inspiration:(slide.inspiration||'').trim()})):(p.slides||[]);Object.assign(p,fields,{image,video,images,slides,mediaInfo});if(oldVideo&&oldVideo!==video&&oldVideo.startsWith('blob:'))URL.revokeObjectURL(oldVideo);createdURL=null;editingPiece=null;closemodal();render();toast(mediaInfo?'Pieza guardada · '+StudioMedia.bytes(mediaInfo.originalBytes)+' → '+StudioMedia.bytes(mediaInfo.bytes)+(mediaInfo.saved?' · −'+mediaInfo.saved+'%':' · '+mediaInfo.note):'Pieza guardada');
 }catch(error){if(createdURL)URL.revokeObjectURL(createdURL);if(error.name!=='AbortError'){toast(error.message||'No se pudo procesar el archivo');if(editingPiece===target){progress.textContent=error.message;button.disabled=false;button.textContent='Guardar pieza';$('#ptype').disabled=false;$('#pfile').disabled=false;}}}finally{target.loading=0;target.controller=null}
}

function stageValidation(d){const pieces=allPieces(d);if(!pieces.length)return 'Agrega al menos una pieza antes de continuar';if(d.stage===0&&(!d.objective.trim()||pieces.some(p=>!pieceInstructionsComplete(p))))return 'Completa el objetivo, el copy y las instrucciones de cada pieza y cada imagen del carrusel';if(d.stage===1&&!/^https:\/\//.test(d.production))return 'Agrega el link de Drive del material de producción';if(d.stage===2&&(!/^https:\/\//.test(d.final)||pieces.some(p=>!piecePreviewComplete(p))))return 'Agrega el Drive final y todas las vistas previas, incluidas las imágenes de cada carrusel';return ''}
function completeContentStage(d,at=new Date().toISOString()){const error=stageValidation(d);if(error)return error;if(d.stage>=6)return 'Este contenido ya está aprobado';d.completed[d.stage]=at;if(d.stage===2)d.reviewReadyAt??=at;if(d.stage===3){d.readyAt??=at;d.adjustments=false}if(d.stage===4)d.sentAt=at;d.stage++;return ''}
function advance(){const d=data(),from=d.stage,error=completeContentStage(d);if(error)return toast(error);recordContentChange(d,from,'Etapa completada');const notification=notifyContent(selected,d);render();toast('Etapa lista · Aviso para '+notification.recipientNames.join(' y '))}
function requestContentChanges(){const d=data(),from=d.stage;d.adjustments=Boolean(d.readyAt);d.stage=2;for(const stage of [2,3,4,5])delete d.completed[stage];recordContentChange(d,from,d.adjustments?'Ajustes del cliente':'Cambios en revisión interna');notifyContent(selected,d,'Ajustes de contenido','Revisa los cambios solicitados antes de volver a marcar Listo.');render();toast('Regresa a Diseño · Aviso interno enviado a Diseño y Marketing')}
function projectClientName(pr){return clients[pr.clientId]?.name||pr.client||'Sin cliente vinculado'}
function projectCommissionCell(pr,part){const commissions=(pr.assignments||[]).filter(a=>a.amount>0);if(!commissions.length)return '<td><span class="pill">Sin comisión</span></td>';return `<td>${commissions.map(a=>{const c=commissionParts(a),amount=part==='advance'?c.advanceAmount:c.deliveryAmount,paid=part==='advance'?c.advancePaid:c.deliveryPaid;return `<div class="commissiondetail projectcommission"><strong class="commissionrecipient">${esc(people[a.person].name)}</strong><div class="commissionpartamount">${paymentMoney(amount)}</div><span class="pill">${amount<=0?'Sin importe':paid?'Pagado':'Pendiente'}</span></div>`}).join('')}</td>`}
function projectDestinationSummary(pr){const grouped=new Map();for(const p of pr.payments||[]){if(p.status==='Anulado'||p.amount<=0)continue;const name=flowAccountName(p.destination)||'Cuenta por registrar';grouped.set(name,(grouped.get(name)||0)+p.amount)}const recorded=(pr.payments||[]).filter(p=>p.status!=='Anulado').reduce((n,p)=>n+p.amount,0),unassigned=Math.round((pr.paid-recorded)*100)/100;if(unassigned>0)grouped.set('Cuenta por registrar',(grouped.get('Cuenta por registrar')||0)+unassigned);return grouped.size?`<div class="projectdestinations"><small>Cuenta destino</small>${Array.from(grouped,([name,amount])=>`<small><strong>${esc(name)}</strong> · ${paymentMoney(amount)}</small>`).join('')}</div>`:''}
function projects(){const list=projectRecords.map((pr,i)=>({pr,i})).filter(({pr})=>pr.period===selectedPeriod()),amount=list.reduce((n,{pr})=>n+pr.amount,0),paid=list.reduce((n,{pr})=>n+pr.paid,0);return heading('Proyectos','Proyectos y pagos vinculados al directorio de clientes.',`${monthselect()}<button class="primary" onclick="projectForm()">+ Nuevo proyecto</button>`)+`<div class="costs">${[['Programado este mes',amount],['Cobrado',paid],['Por cobrar',amount-paid]].map(([l,v])=>`<div class="card"><div class="label">${l}</div><div class="value">${paymentMoney(v)}</div></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>PROYECTO</th><th>CLIENTE</th><th>PRESUPUESTO TOTAL</th><th>COBRADO</th><th>POR COBRAR</th><th>COMISIÓN ANTICIPO</th><th>COMISIÓN ENTREGA</th><th>FECHAS</th><th>ESTADO</th><th>EQUIPO</th><th></th></tr></thead><tbody>${list.map(({pr,i})=>`<tr><td>${esc(pr.name)}</td><td>${esc(projectClientName(pr))}${!clients[pr.clientId]?'<small>Ejemplo sin vincular · Edita para seleccionar cliente</small>':''}</td><td>${paymentMoney(pr.amount)}</td><td><span class="projectamount collected">${paymentMoney(pr.paid)}</span>${projectAdvance(pr)?`<small>Anticipo: ${esc(projectAdvance(pr).date)}</small>`:''}</td><td><span class="projectamount outstanding">${paymentMoney(Math.max(0,pr.amount-pr.paid))}</span></td>${projectCommissionCell(pr,'advance')}${projectCommissionCell(pr,'delivery')}<td><small>Inicio: ${esc(pr.startDate||'Sin definir')}</small><small>Entrega: ${esc(pr.due||'Sin definir')}</small></td><td><span class="pill">${esc(pr.status)}</span></td><td>${pr.assignments.map(a=>`<small>${esc(people[a.person].name)} · ${paymentMoney(a.amount)} · <span class="pill">${commissionParts(a).status}</span></small>`).join('')||'<small>Sin asignar</small>'}</td><td><div class="personactions"><button onclick="projectForm(${i})">Editar</button>${pr.paid<pr.amount?`<button class="paymentaction" onclick="projectPayment(${i})">Registrar pago</button>`:''}</div></td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">No hay proyectos en este mes.</div>':''}</div><p class="hint">Primero da de alta al cliente en Clientes; después selecciónalo al crear su proyecto. Datos temporales del prototipo.</p>`}
function projectAdvance(pr){return (pr.payments||[]).find(p=>p.kind==='advance')}
function updateProjectBalance(){const form=$('#projectform'),total=Number(form.elements.amount.value)||0,advance=Number(form.elements.advance.value)||0,other=Number(form.dataset.otherPaid)||0;$('#projectbalance').value=paymentMoney(total-advance-other);$('#advanceDate').disabled=advance<=0;form.elements.advanceDestination.required=advance>0;const fields=$('#advancefields');fields.hidden=advance<=0;fields.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=advance<=0)}
function commissionParts(a){const amount=Math.round(a.amount*100)/100,advanceAmount=a.advanceAmount==null?Math.round(amount*50)/100:a.advanceAmount,deliveryAmount=Math.round((amount-advanceAmount)*100)/100,advancePaid=a.advancePaid??Boolean(a.paid),deliveryPaid=a.deliveryPaid??Boolean(a.paid),paidAmount=(advancePaid?advanceAmount:0)+(deliveryPaid?deliveryAmount:0);return {advanceAmount,deliveryAmount,advancePaid,deliveryPaid,paidAmount,status:paidAmount>=amount&&amount>0?'Pagada':paidAmount>0?'Parcialmente pagada':'Por pagar'}}
function commissionPartText(a,part){const c=commissionParts(a),advance=part==='advance',amount=advance?c.advanceAmount:c.deliveryAmount,paid=advance?c.advancePaid:c.deliveryPaid;return `${paymentMoney(amount)} · <span class="pill">${amount===0?'Sin importe':paid?'Pagado':'Pendiente'}</span>`}
function updateCommissionSplit(input,halve=false){const row=input.closest('.commissionrow'),total=Number(row.querySelector('[name="commissionAmount"]').value),advance=row.querySelector('[name="commissionAdvance"]');if(halve)advance.value=(Math.round(total*50)/100).toFixed(2);row.querySelector('[name="commissionDelivery"]').value=(Math.round((total-Number(advance.value))*100)/100).toFixed(2);advance.max=total}
function projectCommissionRow(a={person:'',amount:0,paid:false}){const c=commissionParts(a),status=(name,label,paid)=>`<label>${label}<select name="${name}" aria-label="${label}" onchange="toggleCommissionPayout(this)"><option ${!paid?'selected':''}>Pendiente</option><option ${paid?'selected':''}>Pagado</option></select></label><fieldset class="commissionpayout" ${paid?'':'hidden'}>${payoutFields(name==='commissionAdvanceStatus'?'commissionAdvancePayment':'commissionDeliveryPayment',name==='commissionAdvanceStatus'?a.advanceSource:a.deliverySource,name==='commissionAdvanceStatus'?a.advancePaidDate:a.deliveryPaidDate,paid)}</fieldset>`;return `<div class="commissionrow"><label>Colaborador<select name="commissionPerson" aria-label="Colaborador de la comisión"><option value="">Sin asignar</option>${people.map((p,k)=>({p,k})).filter(({p,k})=>!p.deletedAt||a.person===k).map(({p,k})=>`<option value="${k}" ${a.person===k?'selected':''}>${esc(p.name)} · ${esc(p.role)}</option>`).join('')}</select></label><label>Comisión total ($)<input name="commissionAmount" aria-label="Cantidad de comisión" type="number" min="0" step="0.01" value="${a.amount}" oninput="updateCommissionSplit(this,true)" required></label><button type="button" aria-label="Quitar comisión" onclick="this.closest('.commissionrow').remove()">✕</button><div class="commissionphase"><h4>Comisión anticipo</h4><label>Importe anticipo ($)<input name="commissionAdvance" type="number" min="0" max="${a.amount}" step="0.01" value="${c.advanceAmount}" oninput="updateCommissionSplit(this)" required></label>${status('commissionAdvanceStatus','Estado comisión anticipo',c.advancePaid)}<small>Al recibir el anticipo del cliente.</small></div><div class="commissionphase"><h4>Comisión entrega</h4><label>Importe entrega ($)<input name="commissionDelivery" type="number" value="${c.deliveryAmount}" readonly></label>${status('commissionDeliveryStatus','Estado comisión entrega',c.deliveryPaid)}<small>Al entregar y recibir la liquidación del cliente.</small></div></div>`}
function addProjectCommission(){$('#projectcommissions').insertAdjacentHTML('beforeend',projectCommissionRow());applyStateTones($('#projectcommissions'))}
function readProjectCommissions(f){const persons=f.getAll('commissionPerson'),amounts=f.getAll('commissionAmount'),advances=f.getAll('commissionAdvance'),as=f.getAll('commissionAdvanceStatus'),ds=f.getAll('commissionDeliveryStatus'),assignments=[];for(let j=0;j<persons.length;j++){const person=Number(persons[j]),amount=Number(amounts[j]),advanceAmount=Number(advances[j]);if(persons[j]===''&&amount===0)continue;if(persons[j]===''||!Number.isInteger(person)||!people[person]||!Number.isFinite(amount)||amount<0||!Number.isFinite(advanceAmount)||advanceAmount<0||advanceAmount>amount||!['Pendiente','Pagado'].includes(as[j])||!['Pendiente','Pagado'].includes(ds[j]))throw Error('Revisa el colaborador y la división de la comisión: anticipo y entrega deben sumar el total');if(assignments.some(a=>a.person===person))throw Error('Cada colaborador debe aparecer una sola vez en las comisiones del proyecto');const advanceSource=String(f.getAll('commissionAdvancePaymentSource')[j]||''),deliverySource=String(f.getAll('commissionDeliveryPaymentSource')[j]||''),advancePaidDate=String(f.getAll('commissionAdvancePaymentDate')[j]||''),deliveryPaidDate=String(f.getAll('commissionDeliveryPaymentDate')[j]||'');if((as[j]==='Pagado'&&advanceAmount>0&&!validPayout(advanceSource,advancePaidDate))||(ds[j]==='Pagado'&&amount-advanceAmount>0&&!validPayout(deliverySource,deliveryPaidDate)))throw Error('Indica cuenta de salida y fecha en cada comisión pagada');assignments.push({person,amount,advanceAmount,advanceSource,deliverySource,advancePaidDate,deliveryPaidDate,advancePaid:as[j]==='Pagado',deliveryPaid:ds[j]==='Pagado',paid:as[j]==='Pagado'&&ds[j]==='Pagado'})}return assignments}
function projectCommissionEntries(){return projectRecords.filter(pr=>pr.period===selectedPeriod()).flatMap(pr=>pr.assignments.map(a=>({...a,project:pr.name,client:projectClientName(pr)})))}
function financeProjectCommissions(){const entries=projectCommissionEntries(),total=entries.reduce((n,a)=>n+a.amount,0),paid=entries.reduce((n,a)=>n+commissionParts(a).paidAmount,0);return `<div class="sectionline"><h3>Comisiones de proyectos</h3></div><div class="costs">${[['Total comisiones proyectos',total],['Pagadas',paid],['Por pagar',total-paid]].map(([label,value])=>`<div class="card"><span class="label">${label}</span><div class="value">${paymentMoney(value)}</div></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>COLABORADOR</th><th>PROYECTO</th><th>COMISIÓN TOTAL</th><th>COMISIÓN ANTICIPO</th><th>COMISIÓN ENTREGA</th></tr></thead><tbody>${entries.map(a=>`<tr><td>${esc(people[a.person].name)}</td><td>${esc(a.project)}<small>${esc(a.client)}</small></td><td>${paymentMoney(a.amount)}</td><td>${commissionPartText(a,'advance')}</td><td>${commissionPartText(a,'delivery')}</td></tr>`).join('')}</tbody></table>${!entries.length?'<div class="empty">Sin comisiones de proyectos asignadas en el mes.</div>':''}</div>`}
function projectForm(i=null){const pr=i===null?{name:'',clientId:null,amount:0,paid:0,period:selectedPeriod(),status:'En desarrollo'}:projectRecords[i];if(!pr)return;const advance=projectAdvance(pr),otherPaid=pr.paid-(advance?.amount||0);openmodal(modalhead(i===null?'Nuevo proyecto':'Editar proyecto')+`<form id="projectform" data-other-paid="${otherPaid}" onsubmit="saveProject(event,${i})"><p class="hint">Selecciona un cliente registrado en el CRM.</p><div class="formgrid"><label>Cliente del CRM<select aria-label="Cliente del CRM" name="clientId" required style="width:100%;margin-top:7px"><option value="">Seleccionar cliente</option>${clients.map((c,k)=>`<option value="${k}" ${pr.clientId===k?'selected':''}>${esc(c.name)}${c.active?'':' · Inactivo'}</option>`).join('')}</select></label><label>Nombre del proyecto<input name="name" maxlength="150" value="${esc(pr.name)}" required></label><label>Presupuesto total ($)<input name="amount" type="number" step="0.01" min="0.01" value="${pr.amount||''}" oninput="updateProjectBalance()" required></label><label>Anticipo ($)<input name="advance" type="number" step="0.01" min="0" value="${advance?.amount||0}" oninput="updateProjectBalance()" required></label>${paymentDestinationField('advanceDestination',advance?.destination,false)}<label>Fecha del anticipo<input id="advanceDate" name="advanceDate" type="date" value="${esc(advance?.date||mexicoDay())}" required><small>Se guarda con el anticipo en el historial del cliente.</small></label><label class="crmfull">Por cobrar<input id="projectbalance" readonly aria-label="Por cobrar" value="${paymentMoney(pr.amount-pr.paid)}"><small>Presupuesto total − anticipo${otherPaid?' − otros pagos registrados ('+paymentMoney(otherPaid)+')':''}.</small></label><label>Fecha de inicio<input name="startDate" type="date" value="${esc(pr.startDate||'')}" required></label><label>Fecha de entrega<input name="due" type="date" value="${esc(pr.due||'')}" required></label><label>Estado<select name="status" style="width:100%;margin-top:7px">${['En desarrollo','En producción','En revisión','Terminado'].map(t=>`<option ${pr.status===t?'selected':''}>${t}</option>`).join('')}</select></label></div><fieldset id="advancefields" style="border:0;padding:0;margin:20px 0" ${advance?'':'hidden'}><legend>Datos del anticipo</legend><p class="hint">Se guardarán en el historial del cliente junto con este pago.</p><div class="formgrid"><label class="crmfull">Observaciones<textarea name="advanceObservations" maxlength="1500">${esc(advance?.observations||'Anticipo del proyecto')}</textarea></label><label>Método de pago<select name="advanceMethod" onchange="setPaymentDestination(this,'advanceDestination')" style="width:100%;margin-top:7px">${['SPEI','Efectivo','Tarjeta','Depósito bancario','Otro'].map(t=>`<option ${advance?.method===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Cuenta origen<input name="advanceOrigin" maxlength="150" value="${esc(advance?.origin||'')}" placeholder="Banco / titular / últimos 4 dígitos o No aplica"></label></div></fieldset><div class="sectionline"><h3>Comisiones del proyecto</h3></div><div id="projectcommissions">${(pr.assignments?.length?pr.assignments:[{person:'',amount:0,paid:false}]).map(projectCommissionRow).join('')}</div><button type="button" class="wide" onclick="addProjectCommission()">+ Agregar colaborador</button><small>División inicial 50/50. Puedes ajustar el anticipo; la entrega es el resto. Cada parte tiene su propio estado y se paga aparte de las quincenas.</small><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar proyecto</button></div></form>`);updateProjectBalance()}
function projectSaveValues(f,i=null){const pr=i===null?null:projectRecords[i];if(i!==null&&!pr)throw Error('El proyecto ya no está disponible');const clientId=Number(f.get('clientId')),amount=Number(f.get('amount')),advance=Number(f.get('advance')),name=String(f.get('name')||'').trim(),period=String(f.get('startDate')||'').slice(0,7),due=String(f.get('due')||''),startDate=String(f.get('startDate')||''),status=String(f.get('status')||''),oldAdvance=pr?projectAdvance(pr):null,otherPaid=(pr?.paid||0)-(oldAdvance?.amount||0);if(f.get('clientId')===''||!Number.isInteger(clientId)||!clients[clientId]||!name||!Number.isFinite(amount)||amount<=0||!Number.isFinite(advance)||advance<0||Math.round((advance+otherPaid)*100)>Math.round(amount*100)||!/^\d{4}-\d{2}$/.test(period))throw Error('Revisa el cliente, presupuesto y anticipo; los pagos no pueden superar el presupuesto');if(!/^\d{4}-\d{2}-\d{2}$/.test(startDate)||!/^\d{4}-\d{2}-\d{2}$/.test(due)||due<startDate)throw Error('La fecha de entrega debe ser igual o posterior a la fecha de inicio');if(!['En desarrollo','En producción','En revisión','Terminado'].includes(status))throw Error('Revisa el estado del proyecto');const payment=advance>0?{kind:'advance',amount:advance,date:String(f.get('advanceDate')||''),method:String(f.get('advanceMethod')||''),origin:String(f.get('advanceOrigin')||'').trim(),observations:String(f.get('advanceObservations')||'').trim(),destination:String(f.get('advanceDestination')||'')}:null;if(payment&&(!validPayment(payment,amount-otherPaid)||!validPaymentDestination(payment)))throw Error('Completa fecha, método y cuenta destino del anticipo; los pagos en efectivo van a Efectivo');const payments=(pr?.payments||[]).filter(p=>p.kind!=='advance');if(payment)payments.push(payment);const assignments=readProjectCommissions(f);return {clientId,name,amount,period,startDate,due,status,paid:Math.round((otherPaid+advance)*100)/100,payments,assignments}}
function saveProject(e,i=null){e.preventDefault();try{const fields=projectSaveValues(new FormData(e.target),i);if(i===null){projectRecords.push(fields);i=projectRecords.length-1}else Object.assign(projectRecords[i],fields);syncProjectFlow(i);closemodal();render();toast('Proyecto guardado · Anticipo, saldo y entrada en Flujo actualizados')}catch(error){toast(error.message)}}
function clientCharges(i){const charges=Object.entries(retainerMonths).flatMap(([period,rows])=>rows.filter(r=>r.client===i).map(r=>({kind:'Iguala',concept:'Iguala '+period,period,amount:r.fee,paid:r.paid,due:period+'-'+String(Math.min(r.day,new Date(+period.slice(0,4),+period.slice(5),0).getDate())).padStart(2,'0'),payments:(r.payments||[]).filter(p=>p.status!=='Anulado')})));projectRecords.filter(pr=>pr.clientId===i).forEach(pr=>charges.push({kind:'Proyecto',concept:pr.name,period:pr.period,amount:pr.amount,paid:pr.paid,due:pr.due||'',payments:pr.payments||[]}));return charges.sort((a,b)=>a.period.localeCompare(b.period))}
function clientMovements(i){return clientCharges(i).flatMap(c=>{const rows=c.payments.map(p=>({...p,concept:c.concept,kind:c.kind})),undocumented=Math.round((c.paid-c.payments.reduce((n,p)=>n+p.amount,0))*100)/100;if(undocumented>0)rows.push({concept:c.concept,kind:c.kind,amount:undocumented,date:'',method:'Sin registrar',origin:'',observations:'Importe inicial de ejemplo; fecha y cuenta no registradas'});return rows}).sort((a,b)=>(a.date||'').localeCompare(b.date||''))}
function paymentState(c){return c.paid>=c.amount?'Pagado':c.paid>0?'Pago parcial':'Por cobrar'}
function clientHistory(i){const c=clients[i];if(!c)return;const charges=clientCharges(i),movements=clientMovements(i),total=charges.reduce((n,r)=>n+r.amount,0),paid=charges.reduce((n,r)=>n+r.paid,0),pending=charges.reduce((n,r)=>n+Math.max(0,r.amount-r.paid),0);openmodal(modalhead('Historial · '+esc(c.name))+`<p class="hint">Todos los periodos registrados · ${esc(c.contactName||'Contacto pendiente')}</p><button onclick="downloadClientHistory(${i})">Descargar historial CSV ↓</button><div class="costs" style="margin-top:20px">${[['Total contratado',total],['Pagado',paid],['Pendiente',pending]].map(([label,value])=>`<div class="card"><span class="label">${label}</span><div class="value" style="font-size:25px">${paymentMoney(value)}</div></div>`).join('')}</div><h3>Igualas, proyectos y pendientes</h3><div class="tablewrap"><table><thead><tr><th>CONCEPTO</th><th>VENCIMIENTO</th><th>IMPORTE</th><th>PAGADO</th><th>PENDIENTE</th><th>ESTADO</th></tr></thead><tbody>${charges.map(r=>`<tr><td>${esc(r.concept)}</td><td>${esc(r.due||'Sin definir')}</td><td>${paymentMoney(r.amount)}</td><td>${paymentMoney(r.paid)}</td><td>${paymentMoney(Math.max(0,r.amount-r.paid))}</td><td>${paymentState(r)}</td></tr>`).join('')||'<tr><td colspan="6">Sin igualas ni proyectos registrados.</td></tr>'}</tbody></table></div><h3 style="margin-top:24px">Pagos y cuentas de origen</h3><div class="tablewrap"><table><thead><tr><th>FECHA</th><th>CONCEPTO</th><th>MÉTODO</th><th>CUENTA ORIGEN</th><th>MONTO</th><th>OBSERVACIONES</th></tr></thead><tbody>${movements.map(r=>`<tr><td>${esc(r.date||'Sin registrar')}</td><td>${esc(r.concept)}</td><td>${esc(r.method)}</td><td>${esc(r.origin||'Sin registrar')}</td><td>${paymentMoney(r.amount)}</td><td style="white-space:normal;min-width:180px">${esc(r.observations||'—')}</td></tr>`).join('')||'<tr><td colspan="6">Sin pagos registrados.</td></tr>'}</tbody></table></div><p class="hint">Historial informativo del prototipo. Solo incluye los periodos capturados en esta sesión; no es un comprobante fiscal ni un historial importado.</p>`)}
function clientHistoryCSV(i){const c=clients[i],charges=clientCharges(i),movements=clientMovements(i);const rows=[['CLANDESTINO STUDIO · HISTORIAL DEL CLIENTE'],['Cliente',c.name],['Contacto',c.contactName||''],['Correo',c.email||''],['Telefono',c.phone||''],['Direccion',c.address||''],['Datos del prototipo; solo periodos registrados.'],[],['CONCEPTOS Y PENDIENTES'],['Tipo','Concepto','Periodo','Vencimiento','Importe','Pagado','Pendiente','Estado'],...charges.map(r=>[r.kind,r.concept,r.period,r.due,r.amount.toFixed(2),r.paid.toFixed(2),Math.max(0,r.amount-r.paid).toFixed(2),paymentState(r)]),['TOTAL','','','',charges.reduce((n,r)=>n+r.amount,0).toFixed(2),charges.reduce((n,r)=>n+r.paid,0).toFixed(2),charges.reduce((n,r)=>n+Math.max(0,r.amount-r.paid),0).toFixed(2)],[],['PAGOS'],['Fecha','Tipo','Concepto','Metodo','Cuenta origen','Monto','Observaciones'],...movements.map(r=>[r.date||'Sin registrar',r.kind,r.concept,r.method,r.origin||'Sin registrar',r.amount.toFixed(2),r.observations||''])];return '\ufeff'+rows.map(row=>row.map(value=>{let str=String(value??'');if(/^[=+@\-\t\r]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"'}).join(',')).join('\r\n')}
function downloadClientHistory(i){const blob=new Blob([clientHistoryCSV(i)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Historial-'+clients[i].name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Historial descargado para compartir')}
function projectTeam(i){const pr=projectRecords[i];if(!pr)return;openmodal(modalhead('Equipo y pagos · '+esc(pr.name))+`<p class="hint">Comisión total por colaborador, dividida entre anticipo y entrega. Por defecto 50/50; puedes cambiar el importe del anticipo y la entrega se calcula automáticamente.</p><form onsubmit="saveProjectTeam(event,${i})"><div id="projectcommissions">${(pr.assignments.length?pr.assignments:[{person:'',amount:0}]).map(projectCommissionRow).join('')}</div><button type="button" class="wide" onclick="addProjectCommission()">+ Agregar colaborador</button><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar asignaciones</button></div></form>`)}
function saveProjectTeam(e,i){e.preventDefault();const pr=projectRecords[i];if(!pr)return;try{pr.assignments=readProjectCommissions(new FormData(e.target));syncProjectFlow(i);closemodal();render();toast('Comisiones de anticipo y entrega actualizadas')}catch(error){toast(error.message)}}
const expenseCategories={fixed:'Gastos fijos',variable:'Gastos variables',investment:'Gastos inversión'};
let expenseRecords=[];
function expenseTotals(period=selectedPeriod()){return expenseRecords.filter(r=>r.date.slice(0,7)===period).reduce((t,r)=>{t[r.category]+=r.amount;return t},{fixed:0,variable:0,investment:0})}
function expensesView(){const totals=expenseTotals();return heading('Gastos','Registro mensual de gastos fijos, variables e inversión.',`${monthselect()}<button class="primary" onclick="expenseForm()">+ Registrar gasto</button>`)+`<div class="costs">${Object.entries(expenseCategories).map(([key,label])=>`<div class="card"><span class="label">${label}</span><div class="value">${expenseMoney(totals[key])}</div></div>`).join('')}</div>${Object.entries(expenseCategories).map(([category,label])=>{const rows=expenseRecords.map((r,i)=>({r,i})).filter(({r})=>r.category===category&&r.date.slice(0,7)===selectedPeriod());return `<section class="expensesection" aria-label="${label}"><div class="sectionline"><h2>${label}</h2><button onclick="expenseForm(null,'${category}')">+ Agregar</button></div><div class="tablewrap"><table><thead><tr><th>CONCEPTO</th><th>FECHA</th><th>OBSERVACIONES</th><th>MONTO</th><th></th></tr></thead><tbody>${rows.map(({r,i})=>`<tr><td>${esc(r.name)}</td><td>${esc(r.date)}</td><td class="expensenotes">${esc(r.notes||'—')}</td><td>${expenseMoney(r.amount)}</td><td><button onclick="expenseForm(${i})">Editar</button></td></tr>`).join('')}</tbody><tfoot><tr><td colspan="3">Total ${label.toLowerCase()}</td><td>${expenseMoney(totals[category])}</td><td></td></tr></tfoot></table>${!rows.length?'<div class="empty">Sin gastos registrados en esta sección durante el mes.</div>':''}</div></section>`}).join('')}<p class="hint">Cada gasto pertenece al mes de su fecha. Al editar el concepto, monto, fecha o categoría, se actualizan Vista General y la gráfica anual. Los gastos fijos se registran por mes; todavía no se repiten automáticamente.</p><p class="hint">Datos temporales y de ejemplo del prototipo.</p>`}
function expenseForm(i=null,category='fixed'){const r=i===null?{name:'',category,amount:'',date:selectedPeriod()===mexicoDay().slice(0,7)?mexicoDay():selectedPeriod()+'-01',notes:''}:expenseRecords[i];if(!r)return;openmodal(modalhead(i===null?'Registrar gasto':'Editar gasto')+`<form onsubmit="saveExpense(event,${i})"><div class="formgrid"><label>Concepto<input name="name" value="${esc(r.name)}" maxlength="160" placeholder="Ej. Renta, pauta o compra de computadora" required></label><label>Tipo de gasto<select aria-label="Tipo de gasto" name="category" style="width:100%;margin-top:7px" required>${Object.entries(expenseCategories).map(([key,label])=>`<option value="${key}" ${r.category===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Monto ($)<input name="amount" type="number" min="0" step="0.01" value="${r.amount}" required></label><label>Fecha<input name="date" type="date" value="${esc(r.date)}" required></label><label class="crmfull">Observaciones<textarea name="notes" maxlength="1000" placeholder="Proveedor, referencia o detalle de la compra">${esc(r.notes)}</textarea></label></div><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar gasto</button></div></form>`)}
function expenseValues(f){const name=String(f.get('name')||'').trim(),category=String(f.get('category')||''),amount=Number(f.get('amount')),date=String(f.get('date')||''),notes=String(f.get('notes')||'').trim();if(!name||!expenseCategories[category]||!Number.isFinite(amount)||amount<0||!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Revisa el concepto, tipo, monto y fecha del gasto');return {name,category,amount:Math.round(amount*100)/100,date,notes}}
function saveExpense(e,i=null){e.preventDefault();try{const fields=expenseValues(new FormData(e.target));if(i===null)expenseRecords.push(fields);else{if(!expenseRecords[i])throw Error('Este gasto ya no está disponible');Object.assign(expenseRecords[i],fields)}closemodal();render();toast('Gasto guardado · Resumen y utilidad actualizados')}catch(error){toast(error.message)}}
function financeConcentration(){const t=totals(),rows=monthlyRows(),prs=projectRecords.filter(pr=>pr.period===selectedPeriod()),retainersPaid=rows.filter(r=>r.paid>=r.fee).length,projectsPaid=prs.filter(pr=>pr.paid>=pr.amount).length,base=people.reduce((n,p)=>n+p.base,0),comm=clients.filter(c=>c.active).reduce((n,c)=>n+c.comm.reduce((a,v)=>a+v,0),0),projectCommissions=prs.reduce((n,pr)=>n+pr.assignments.reduce((a,v)=>a+v.amount,0),0);const blocks=[['Ventas',[['Igualas',t.fees],['Proyectos',t.projectSales],['Venta total',t.sales]]],['Cobros recibidos',[['Igualas cobradas',t.collected],['Proyectos cobrados',t.paid-t.collected],['Cobrado total',t.paid]]],['Gastos',[['Gastos fijos',t.fixed],['Gastos variables',t.variable],['Gastos inversión',t.investment],['Total de gastos',t.fixed+t.variable+t.investment]]],['Composición de nómina',[['Sueldos fijos',base],['Comisiones igualas',comm],['Comisiones proyectos',projectCommissions],['Nómina total',t.pay]]]];return `<div class="financeblocks">${blocks.map(([title,items])=>`<section class="card"><h2>${title}</h2>${items.map(([label,value])=>`<div class="financenumber"><span>${label}</span><strong>${title==='Gastos'?expenseMoney(value):paymentMoney(value)}</strong></div>`).join('')}</section>`).join('')}</div><p class="hint">Igualas: ${retainersPaid} pagadas / ${rows.length-retainersPaid} por cobrar. Proyectos: ${projectsPaid} pagados / ${prs.length-projectsPaid} por cobrar; los abonos parciales permanecen por cobrar.</p><div class="profits"><div class="profit"><span class="label">Utilidad sobre venta total</span><div class="value">${paymentMoney(t.sales-t.cost)}</div><small>Venta total menos gastos, inversión y nómina programada.</small></div><div class="profit actual"><span class="label">Resultado sobre lo cobrado</span><div class="value">${paymentMoney(t.paid-t.cost)}</div><small>Cobros recibidos menos los mismos costos programados del mes.</small></div></div>`}
function finance(){const retainers=monthlyRows().filter(r=>r.paid<r.fee),projects=projectRecords.map((pr,i)=>({pr,i})).filter(({pr})=>pr.period===selectedPeriod()&&pr.paid<pr.amount),retainerBalance=retainers.reduce((n,r)=>n+Math.max(0,r.fee-r.paid),0),projectBalance=projects.reduce((n,{pr})=>n+Math.max(0,pr.amount-pr.paid),0);return heading('Finanzas','Concentrado mensual de ventas, gastos, cobros y nómina.',monthselect())+financeConcentration()+`<div class="sectionline"><h2>Cuentas por cobrar</h2><span class="hint">${names[+month-1]} ${year}</span></div><div class="receivable">${[['Igualas pendientes',retainerBalance],['Proyectos pendientes',projectBalance],['Total por cobrar',retainerBalance+projectBalance]].map(([label,amount])=>`<div><span class="label">${label}</span><div class="value">${paymentMoney(amount)}</div></div>`).join('')}</div><section class="expensesection"><div class="sectionline"><h2>Igualas por cobrar</h2><button onclick="go('Igualas')">Ver igualas ↗</button></div><div class="tablewrap"><table><thead><tr><th>CLIENTE</th><th>IGUALA</th><th>COBRADO</th><th>PENDIENTE</th><th></th></tr></thead><tbody>${retainers.map(r=>`<tr><td>${esc(r.name)}</td><td>${paymentMoney(r.fee)}</td><td>${paymentMoney(r.paid)}</td><td>${paymentMoney(Math.max(0,r.fee-r.paid))}</td><td><button class="paymentaction" onclick="payment(${r.client},'${selectedPeriod()}')">Registrar pago</button></td></tr>`).join('')}</tbody></table>${!retainers.length?'<div class="empty">Sin igualas pendientes registradas en este mes.</div>':''}</div></section><section class="expensesection"><div class="sectionline"><h2>Proyectos por cobrar</h2><button onclick="go('Proyectos')">Ver proyectos ↗</button></div><div class="tablewrap"><table><thead><tr><th>CLIENTE / PROYECTO</th><th>PRESUPUESTO</th><th>COBRADO</th><th>PENDIENTE</th><th></th></tr></thead><tbody>${projects.map(({pr,i})=>`<tr><td>${esc(projectClientName(pr))}<small>${esc(pr.name)}</small></td><td>${paymentMoney(pr.amount)}</td><td>${paymentMoney(pr.paid)}</td><td>${paymentMoney(Math.max(0,pr.amount-pr.paid))}</td><td><button class="paymentaction" onclick="projectPayment(${i})">Registrar pago</button></td></tr>`).join('')}</tbody></table>${!projects.length?'<div class="empty">Sin proyectos pendientes registrados en este mes.</div>':''}</div></section>${financePayroll()}<p class="hint">Todos los importes se alimentan de Igualas, Proyectos, Gastos y Colaboradores. Los estados y datos del prototipo son temporales durante la sesión.</p>`}
let flowAccounts=[{id:'cash',name:'Efectivo',kind:'cash'},{id:'bbva',name:'BBVA FISCAL',kind:'bank'},{id:'mp',name:'MERCADO PAGO',kind:'bank'}],flowRecords=[],flowBankFilter='all',flowAccountId=1;
function flowSigned(r){return r.type==='Entrada'?r.amount:-r.amount}
function flowSummary(kind,account='all',period=selectedPeriod()){const records=flowRecords.map((r,i)=>({r,i})).filter(({r})=>flowAccounts.some(a=>a.id===r.account&&a.kind===kind)&&(account==='all'||r.account===account)),opening=records.filter(({r})=>r.date.slice(0,7)<period).reduce((n,{r})=>n+flowSigned(r),0),rows=records.filter(({r})=>r.date.slice(0,7)===period).sort((a,b)=>a.r.date.localeCompare(b.r.date)||a.i-b.i),incoming=rows.filter(({r})=>r.type==='Entrada').reduce((n,{r})=>n+r.amount,0),outgoing=rows.filter(({r})=>r.type==='Salida').reduce((n,{r})=>n+r.amount,0);let balance=opening;return {opening,incoming,outgoing,closing:Math.round((opening+incoming-outgoing)*100)/100,rows:rows.map(item=>({...item,balance:Math.round((balance+=flowSigned(item.r))*100)/100}))}}
function flowSection(kind){const bank=kind==='bank',account=bank?flowBankFilter:'cash',t=flowSummary(kind,account),title=bank?'Flujo en bancos':'Flujo de efectivo';return `<section class="flowsection" aria-label="${title}"><div class="sectionline"><h2>${title}</h2><button class="primary" onclick="flowForm(null,'${bank?(account==='all'?'bbva':account):'cash'}')">+ Registrar movimiento</button></div>${bank?`<div class="toolbar flowaccountbar"><label>Cuenta bancaria<select aria-label="Filtrar cuenta bancaria" onchange="flowBankFilter=this.value;render()"><option value="all">Todas las cuentas</option>${flowAccounts.filter(a=>a.kind==='bank').map(a=>`<option value="${a.id}" ${account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><button onclick="flowAccountForm()">+ Agregar cuenta</button></div>`:''}<div class="flowtotals">${[['Saldo inicial',t.opening],['Entradas del mes',t.incoming],['Salidas del mes',-t.outgoing],['Saldo al cierre del mes',t.closing]].map(([label,value])=>`<div class="card"><span class="label">${label}</span><div class="value">${value<0?'-':''}${paymentMoney(Math.abs(value))}</div></div>`).join('')}</div><div class="tablewrap"><table class="flowtable"><thead><tr><th>FECHA</th>${bank?'<th>CUENTA</th>':''}<th>CONCEPTO</th><th>NOTA / DETALLE</th><th>ENTRADA</th><th>SALIDA</th><th>SALDO</th><th></th></tr></thead><tbody>${t.rows.map(({r,i,balance})=>`<tr><td>${esc(r.date)}</td>${bank?`<td>${esc(flowAccounts.find(a=>a.id===r.account)?.name)}</td>`:''}<td><strong>${esc(r.concept)}</strong>${isLinkedFlow(r)?'<small>Movimiento automático</small>':''}</td><td class="flownote">${esc(r.notes||'—')}</td><td>${r.type==='Entrada'?'+'+paymentMoney(r.amount):'—'}</td><td>${r.type==='Salida'?'-'+paymentMoney(r.amount):'—'}</td><td><strong>${balance<0?'-':''}${paymentMoney(Math.abs(balance))}</strong></td><td>${isLinkedFlow(r)?`<button onclick="openFlowSource(${i})">Ver origen</button>`:`<button onclick="flowForm(${i})">Editar</button>`}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="${bank?4:3}">Total del mes</td><td>+${paymentMoney(t.incoming)}</td><td>-${paymentMoney(t.outgoing)}</td><td>${t.closing<0?'-':''}${paymentMoney(Math.abs(t.closing))}</td><td></td></tr></tfoot></table>${!t.rows.length?'<div class="empty">Sin movimientos registrados en este mes.</div>':''}</div><p class="hint">Saldo inicial: movimientos capturados antes del mes. Saldo al cierre: saldo inicial + entradas − salidas.${bank&&account==='all'?' Vista consolidada de todas las cuentas bancarias.':''}</p></section>`}
function flowView(){return heading('Flujo','Entradas y salidas por mes y cuenta.',retainerMonthSelect().replaceAll('de igualas','de flujo'))+flowSection('cash')+flowSection('bank')+`<p class="hint">Los cobros de igualas y proyectos, y los pagos a colaboradores con cuenta registrada, aparecen automáticamente aquí. Captura manualmente los demás movimientos y su concepto. Para comenzar con un saldo existente, registra una entrada con el concepto “Saldo inicial”. Los movimientos automáticos se corrigen desde su registro de origen; no los captures otra vez. Los movimientos manuales no cambian ventas, gastos ni cobros de otros apartados. Datos temporales del prototipo.</p>`}
function flowForm(i=null,account='cash'){const r=i===null?{account,type:'Entrada',amount:'',date:mexicoDay(),concept:'',notes:''}:flowRecords[i];if(!r)return;if(isLinkedFlow(r))return toast('Este movimiento se modifica desde su registro de origen');openmodal(modalhead(i===null?'Registrar movimiento':'Editar movimiento')+`<form onsubmit="saveFlow(event,${i})"><div class="formgrid"><label>Medio / cuenta<select name="account" style="width:100%;margin-top:7px" required>${flowAccounts.map(a=>`<option value="${a.id}" ${r.account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Movimiento<select name="type" style="width:100%;margin-top:7px"><option ${r.type==='Entrada'?'selected':''}>Entrada</option><option ${r.type==='Salida'?'selected':''}>Salida</option></select></label><label>Fecha<input name="date" type="date" value="${esc(r.date)}" required></label><label>Monto ($)<input name="amount" type="number" min="0.01" step="0.01" value="${r.amount}" required></label><label class="crmfull">Concepto<input name="concept" maxlength="180" value="${esc(r.concept)}" placeholder="Ej. Pago de cliente, renta, compra de material…" required></label><label class="crmfull">Nota / detalle<textarea name="notes" maxlength="1500" placeholder="Explica de qué fue la entrada o salida">${esc(r.notes)}</textarea></label></div><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar movimiento</button></div></form>`)}
function flowValues(f){const account=String(f.get('account')||''),type=String(f.get('type')||''),date=String(f.get('date')||''),amount=Number(f.get('amount')),concept=String(f.get('concept')||'').trim(),notes=String(f.get('notes')||'').trim();if(!flowAccounts.some(a=>a.id===account)||!['Entrada','Salida'].includes(type)||!Number.isFinite(amount)||amount<=0||Math.round(amount*100)<=0||!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date||!concept)throw Error('Revisa la cuenta, tipo, fecha, monto y concepto');return {account,type,date,amount:Math.round(amount*100)/100,concept,notes}}
function saveFlow(e,i=null){e.preventDefault();try{const fields=flowValues(new FormData(e.target));if(i===null)flowRecords.push(fields);else{if(!flowRecords[i])throw Error('Movimiento no disponible');if(isLinkedFlow(flowRecords[i]))throw Error('Este movimiento se modifica desde su registro de origen');flowRecords[i]=fields}year=fields.date.slice(0,4);month=String(Number(fields.date.slice(5,7)));if(fields.account!=='cash')flowBankFilter=fields.account;closemodal();render();toast('Movimiento guardado · Saldos actualizados')}catch(error){toast(error.message)}}
function flowAccountForm(){openmodal(modalhead('Agregar cuenta bancaria')+`<form onsubmit="saveFlowAccount(event)"><label>Nombre de la cuenta<input name="name" maxlength="80" placeholder="Ej. BBVA FISCAL" required></label><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar cuenta</button></div></form>`)}
function saveFlowAccount(e){e.preventDefault();const name=String(new FormData(e.target).get('name')||'').trim();if(!name||flowAccounts.some(a=>a.name.toLowerCase()===name.toLowerCase()))return toast('Escribe un nombre de cuenta diferente');const id='bank'+flowAccountId++;flowAccounts.push({id,name,kind:'bank'});flowBankFilter=id;closemodal();render();toast('Cuenta bancaria agregada')}
function flowAccountName(id){return flowAccounts.find(a=>a.id===id)?.name||''}
function validPayout(source,date){return Boolean(flowAccountName(source))&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date))&&new Date(date).toISOString().slice(0,10)===date}
function payoutFields(prefix,source='',date='',required=true){return `<label>Cuenta de salida<select name="${prefix}Source" aria-label="Cuenta de salida" ${required?'required':''} style="width:100%;margin-top:7px"><option value="">Seleccionar cuenta</option>${flowAccounts.map(a=>`<option value="${a.id}" ${a.id===source?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Fecha del pago<input name="${prefix}Date" type="date" value="${esc(date||mexicoDay())}" ${required?'required':''}></label>`}
function toggleCommissionPayout(select){const panel=select.closest('.commissionphase').querySelector('.commissionpayout'),paid=select.value==='Pagado';panel.hidden=!paid;panel.querySelectorAll('input,select').forEach(el=>el.required=paid);applyStateTones(panel)}
function syncRetainerFlow(i,period){const key=period+':'+i,record=monthlyRows(period).find(r=>r.client===i);flowRecords=flowRecords.filter(r=>r.sourceRetainer!==key);if(!record)return;(record.payments||[]).forEach(p=>{if(p.status==='Anulado'||p.amount<=0||!p.destination||!validPaymentDestination(p))return;flowRecords.push({sourceRetainer:key,client:i,period,account:p.destination,type:'Entrada',date:p.date,amount:p.amount,concept:'Cobro de iguala · '+record.name+' · '+period,notes:p.method+(p.origin?' · Origen: '+p.origin:'')+(p.observations?' · '+p.observations:'')})})}
function quincenaPaymentForm(k,q,period=selectedPeriod()){if(period!==selectedPeriod()||!people[k])return;const record=quincenaRecord(k,q),state=quincenaState(k,q);openmodal(modalhead('Pago de quincena '+q+' · '+esc(people[k].name))+`<p>${esc(period)} · Importe: <strong>${paymentMoney(state.amount)}</strong></p><form onsubmit="saveQuincenaPayment(event,${k},${q},'${period}')"><div class="formgrid">${payoutFields('payroll',record?.source,record?.date)}</div><p class="hint">Al guardar se marca Pagado y se registra una salida en Flujo. Es un registro del pago, no una transferencia bancaria.</p><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar pago</button></div></form>`)}
function applyQuincenaPayment(k,q,period,source,date){if(!people[k]||![1,2].includes(q)||period!==selectedPeriod()||!validPayout(source,date))return false;const amount=quincenaState(k,q).amount;if(amount<=0)return false;payrollStatuses[period]??={};payrollStatuses[period][k]??={};payrollStatuses[period][k][q]={paid:true,amount,source,date,updatedAt:new Date().toISOString()};syncPayrollFlow(k,q,period);return true}
function saveQuincenaPayment(e,k,q,period){e.preventDefault();const f=new FormData(e.target);if(!applyQuincenaPayment(k,q,period,String(f.get('payrollSource')||''),String(f.get('payrollDate')||'')))return toast('Revisa la cuenta de salida y fecha del pago');closemodal();render();toast('Quincena pagada · Salida registrada en Flujo')}
function syncPayrollFlow(k,q,period){const key=period+':'+k+':'+q,r=quincenaRecord(k,q,period);flowRecords=flowRecords.filter(f=>f.sourcePayroll!==key);if(r?.paid&&r.amount>0&&validPayout(r.source,r.date))flowRecords.push({sourcePayroll:key,person:k,q,period,account:r.source,type:'Salida',amount:r.amount,date:r.date,concept:'Nómina · '+people[k].name+' · Quincena '+q,notes:'Periodo '+period})}
function syncProjectCommissionFlow(i){const pr=projectRecords[i];if(!pr)return;(pr.assignments||[]).forEach(a=>{const c=commissionParts(a);[['advance',c.advanceAmount,c.advancePaid,a.advanceSource,a.advancePaidDate,'anticipo'],['delivery',c.deliveryAmount,c.deliveryPaid,a.deliverySource,a.deliveryPaidDate,'entrega']].forEach(([part,amount,paid,source,date,label])=>{if(paid&&amount>0&&validPayout(source,date))flowRecords.push({sourceProject:i,sourceCommission:true,account:source,type:'Salida',amount,date,concept:'Comisión '+label+' · '+people[a.person].name,notes:pr.name+' · '+projectClientName(pr)})})})}
function isLinkedFlow(r){return Number.isInteger(r.sourceProject)||Boolean(r.sourceRetainer||r.sourcePayroll)}
function openFlowSource(i){const r=flowRecords[i];if(!r)return;closemodal();if(r.sourceRetainer){year=r.period.slice(0,4);month=String(Number(r.period.slice(5)));go('Igualas');retainerPayments(r.client,r.period)}else if(r.sourcePayroll){year=r.period.slice(0,4);month=String(Number(r.period.slice(5)));go('Colaboradores');quincenaPaymentForm(r.person,r.q,r.period)}else if(Number.isInteger(r.sourceProject)){go('Proyectos');projectForm(r.sourceProject)}}
let internalNotifications=[],nextNotificationId=1;
function unreadNotifications(recipient='direction'){return internalNotifications.filter(n=>n.recipients.includes(recipient)&&!n.readBy.includes(recipient)).length}
function updateNotificationBadge(){const button=$('#notificationbutton');if(!button)return;const count=unreadNotifications();button.innerHTML='♧'+(count?`<span class="notificationbadge">${count}</span>`:'');button.setAttribute('aria-label','Notificaciones'+(count?' · '+count+' sin leer':''))}
function recipientLabel(id){return id==='direction'?'Dirección':people[Number(id.split(':')[1])]?.name||'Sin asignar'}
function contentRecipientIds(c,stage){const person=j=>Number.isInteger(c.team[j])&&people[c.team[j]]?['person:'+c.team[j]]:[],marketing=person(0);if(stage===0)return marketing;if(stage===1)return person(1);if(stage===2)return [...person(2),...marketing];return ['direction',...marketing]}
function notifyContent(i,d,title='',body=''){const c=clients[i],stage=d.stage;let recipients=contentRecipientIds(c,stage);if(stage===2&&!title)recipients=recipients.filter(id=>id==='person:'+c.team[2]);if(!recipients.length)recipients=['direction'];recipients=[...new Set(recipients)];const titles=['Marketing pendiente','Marketing listo · Sigue Fotografía / Video','Fotografía / Video listo · Sigue Diseño','Diseño listo · Revisión de Dirección y Marketing','Listo para mostrar al cliente','Contenido en revisión del cliente','Contenido aprobado'];const n={id:nextNotificationId++,client:i,period:selectedPeriod(),stage,title:title||titles[stage],body:body||('Contenido de '+c.name+' · '+selectedPeriod()+' · '+stages[stage]),recipients,recipientNames:recipients.map(recipientLabel),readBy:[],at:new Date().toISOString()};internalNotifications.unshift(n);updateNotificationBadge();return n}
function recordContentChange(d,from,reason){d.log??=[];d.log.push({from,to:d.stage,reason,actor:'Dirección · Sesión de demostración',at:new Date().toISOString()})}
function showNotifications(recipient='direction'){const list=internalNotifications.filter(n=>recipient==='all'||n.recipients.includes(recipient));openmodal(modalhead('Avisos internos')+`<label>Ver avisos de<select aria-label="Ver avisos de" onchange="showNotifications(this.value)" style="width:100%;margin:7px 0 18px"><option value="direction" ${recipient==='direction'?'selected':''}>Dirección</option><option value="all" ${recipient==='all'?'selected':''}>Todo el equipo</option>${people.map((p,k)=>`<option value="person:${k}" ${recipient==='person:'+k?'selected':''}>${esc(p.name)} · ${esc(p.role)}</option>`).join('')}</select></label><div class="notificationlist">${list.map(n=>`<article class="notificationitem"><div class="cardline"><strong>${esc(clients[n.client]?.name||'Marca')}</strong><span class="pill">${recipient!=='all'&&n.readBy.includes(recipient)?'Leído':'Nuevo'}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>Para: ${esc(n.recipientNames.join(' · '))}</small><small>${esc(new Date(n.at).toLocaleString('es-MX',{timeZone:'America/Mexico_City'}))} · ${esc(n.period)}</small><button onclick="openContentNotification(${n.id},'${recipient}')">Abrir contenido</button></article>`).join('')||'<div class="empty">No hay avisos para esta persona.</div>'}</div><p class="hint">Avisos internos de esta sesión de demostración. No se envían correos, WhatsApp ni notificaciones al teléfono; la entrega entre usuarios requiere conectar las cuentas y el guardado permanente.</p>`)}
function openContentNotification(id,recipient){const n=internalNotifications.find(n=>n.id===id);if(!n)return;if(n.recipients.includes(recipient)&&!n.readBy.includes(recipient))n.readBy.push(recipient);closemodal();year=n.period.slice(0,4);month=String(Number(n.period.slice(5)));openBrand(n.client)}
function adminStageForm(){const d=data();openmodal(modalhead('Corregir etapa · Dirección')+`<form onsubmit="saveAdminStage(event)"><label>Etapa<select name="stage" style="width:100%;margin-top:7px">${stages.map((label,i)=>`<option value="${i}" ${d.stage===i?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label style="margin-top:18px">Motivo de la corrección<textarea name="reason" maxlength="1000" required placeholder="Explica el cambio de etapa"></textarea></label><p class="hint">Este control permite corregir el avance sin las validaciones de entrega. El cambio y su motivo quedan en la bitácora y generan un aviso interno.</p><div class="formactions"><button type="button" onclick="closemodal()">Cancelar</button><button class="primary">Guardar corrección</button></div></form>`)}
function applyAdminStage(d,stage,reason){if(!Number.isInteger(stage)||stage<0||stage>=stages.length||!reason.trim())return false;const from=d.stage;if(stage===from)return false;for(const key of Object.keys(d.completed))if(Number(key)>=stage)delete d.completed[key];d.stage=stage;if(stage<3)delete d.reviewReadyAt;else d.reviewReadyAt??=new Date().toISOString();if(stage<4){delete d.readyAt;delete d.sentAt;d.adjustments=false}else{d.readyAt??=new Date().toISOString();if(stage<5)delete d.sentAt;else d.sentAt??=new Date().toISOString()}recordContentChange(d,from,reason.trim());return true}
function saveAdminStage(e){e.preventDefault();const f=new FormData(e.target),d=data(),reason=String(f.get('reason')||'');if(!applyAdminStage(d,Number(f.get('stage')),reason))return toast('Elige una etapa diferente y escribe el motivo');notifyContent(selected,d,'Dirección corrigió la etapa',reason.trim());closemodal();render();toast('Etapa corregida · Bitácora y avisos actualizados')}
function showContentLog(){const log=data().log||[];openmodal(modalhead('Bitácora de contenido · '+esc(clients[selected].name))+`<div class="tablewrap"><table><thead><tr><th>FECHA</th><th>DE</th><th>A</th><th>MOTIVO</th></tr></thead><tbody>${log.slice().reverse().map(r=>`<tr><td>${esc(new Date(r.at).toLocaleString('es-MX',{timeZone:'America/Mexico_City'}))}<small>${esc(r.actor)}</small></td><td>${esc(stages[r.from])}</td><td>${esc(stages[r.to])}</td><td>${esc(r.reason)}</td></tr>`).join('')||'<tr><td colspan="4">Sin cambios registrados en esta sesión.</td></tr>'}</tbody></table></div>`)}
function generalNotesData(doc){if(!doc.generalNotesMigrated){const legacy=Object.entries(contentGroups).flatMap(([group,cfg])=>(doc[group]||[]).map((p,i)=>p.internalNotes?.trim()?cfg.single+' '+(i+1)+': '+p.internalNotes.trim():'')).filter(Boolean);if(legacy.length)doc.generalNotes=[doc.generalNotes||'',...legacy].filter(Boolean).join('\n\n');doc.generalNotesMigrated=true}return doc}
function generalNotesPanel(){const d=generalNotesData(data());return `<section class="generalnotes"><div class="cardline"><h2>Correcciones / Observaciones</h2>${d.generalNotes?.trim()?`<span class="pill">${d.generalNotesResolved?'Resuelto':d.generalNotesSentAt?'Enviado a Diseño':'Pendiente'}</span>`:''}</div><p class="hint">Opcional · Notas generales de Dirección y Marketing para Diseño. Escribe manualmente la pieza o imagen a corregir. El cliente no ve este campo.</p><form onsubmit="saveGeneralNotes(event)"><label>Observaciones internas de la parrilla<textarea name="notes" maxlength="6000" oninput="data().generalNotesDraft=this.value" placeholder="Ej. Post 3: aumentar el título. Carrusel 2, imagen 4: cambiar el fondo. Story 1: corregir el precio…">${esc(d.generalNotesDraft??d.generalNotes??'')}</textarea></label><div class="generalnotesactions"><label class="internalresolved"><input name="resolved" type="checkbox" ${d.generalNotesResolved?'checked':''}>Cambios resueltos</label><div><button value="save">Guardar observaciones</button>${d.stage>=3?'<button class="primary" value="send">Guardar y enviar a Diseño</button>':''}</div></div></form></section>`}
function applyGeneralNotes(doc,text,resolved=false){generalNotesData(doc);text=String(text||'').trim().slice(0,6000);if(text!==(doc.generalNotes||'')||Boolean(resolved)!==Boolean(doc.generalNotesResolved)){doc.generalNotesHistory??=[];doc.generalNotesHistory.push({text:doc.generalNotes||'',resolved:Boolean(doc.generalNotesResolved),at:new Date().toISOString(),actor:'Revisión interna · Demo'});doc.generalNotesUpdatedAt=new Date().toISOString()}if(text!==(doc.generalNotes||''))delete doc.generalNotesSentAt;doc.generalNotes=text;doc.generalNotesResolved=Boolean(text&&resolved);delete doc.generalNotesDraft}
function sendGeneralNotes(doc){if(!doc.generalNotes?.trim())return false;const from=doc.stage;doc.stage=2;doc.adjustments=Boolean(doc.readyAt);for(const stage of [2,3,4,5])delete doc.completed[stage];doc.generalNotesResolved=false;doc.generalNotesSentAt=new Date().toISOString();recordContentChange(doc,from,'Correcciones generales de la parrilla');notifyContent(selected,doc,'Correcciones generales para Diseño',doc.generalNotes);return true}
function saveGeneralNotes(e){e.preventDefault();const f=new FormData(e.target),send=e.submitter?.value==='send',text=String(f.get('notes')||'').trim(),d=data();if(send&&!text)return toast('Puedes guardar el campo vacío; para enviar ajustes escribe las observaciones');applyGeneralNotes(d,text,send?false:f.get('resolved')==='on');if(send)sendGeneralNotes(d);render();toast(send?'Correcciones enviadas a Diseño · Aviso interno creado':'Observaciones generales guardadas')}
function stateTone(text){const label=String(text).trim().toLowerCase();if(/^(resuelto|registrado|pagad[oa]s?|liquidad[oa]s?|activ[oa]s?|completad[oa]s?|terminad[oa]s?|aprobad[oa]s?|listo(?: para cliente)?)$/.test(label))return 'positive';if(/^(enviado a diseño|eliminado|anulado|por cobrar|por pagar|pendientes?|inactiv[oa]s?|suspendid[oa]s?|por revisar|ajustes solicitados|pago parcial|parcialmente pagada|sin comisi[oó]n|sin importe|en desarrollo|en producci[oó]n|en revisi[oó]n|en proceso)$/.test(label))return 'muted';return ''}
function applyStateTones(root=document){root.querySelectorAll('.pill,select,.tabs button').forEach(el=>{const text=el.tagName==='SELECT'?el.selectedOptions[0]?.textContent:el.classList.contains('pill')?el.textContent:Array.from(el.childNodes).filter(n=>n.nodeType===3).map(n=>n.textContent).join(''),tone=stateTone(text);if(tone)el.dataset.state=tone;else delete el.dataset.state})}
document.addEventListener('change',event=>{if(event.target.matches('select'))applyStateTones()});
$('#modal').addEventListener('cancel',()=>{if(editingPiece){editingPiece.controller?.abort();editingPiece=null}});
render();
